    @mcp.tool()
    def rule_import_job_create(
        campaign_id: str,
        artifact: str,
        source_key: str,
        title: str,
        edition: str,
        locale: str = "en",
        publication_id: str = "",
        version: str = "",
        authority: str = "supplement",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Create a reviewable rulebook import job for an already staged artifact."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        edition = normalize_dnd_edition(edition)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for an import job")
        payload = {
            "artifact": artifact,
            "source_key": source_key,
            "title": title,
            "edition": edition,
            "locale": locale,
            "publication_id": publication_id,
            "version": version,
            "authority": authority,
        }
        scope = f"import-job-create:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        storage.artifact_rulebook_path(artifact)
        job = import_jobs.create(
            campaign_id=campaign_id,
            kind="rulebook",
            artifact=artifact,
            artifact_checksum=storage.rulebook_checksum(artifact),
            payload=payload,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {"job": import_job_view(result)},
            ),
        )
        return {"job": import_job_view(job)}

    @mcp.tool()
    def rule_import_job_inspect(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Normalize a staged rulebook and persist the parser report before indexing it."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for import inspection")
        job = require_import_job(campaign_id, job_id, "rulebook")
        payload = {"job_id": job_id, "operation": "inspect"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        inspection = rules.inspect_path(
            storage.artifact_rulebook_path(job.artifact),
            **rule_document_options(job.artifact_checksum),
        )
        updated = import_jobs.record_inspection(
            job_id,
            inspection,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "inspection": inspection,
                },
            ),
        )
        return {"job": import_job_view(updated), "inspection": inspection}

    @mcp.tool()
    @_agent_ruling_boundary
    def rule_import_job_ingest(
        campaign_id: str,
        job_id: str,
        acknowledge_warnings: bool = False,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Index an inspected rulebook, retaining its source id for candidate citations."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for rulebook indexing")
        job = require_import_job(campaign_id, job_id, "rulebook")
        payload = {
            "job_id": job_id,
            "operation": "ingest",
            "acknowledge_warnings": acknowledge_warnings,
        }
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"inspected", "failed"}:
            raise ValueError("rule import job must be inspected before indexing")
        warnings = list(dict(job.inspection or {}).get("warnings") or [])
        if warnings and not acknowledge_warnings:
            raise NeedsRulingError(
                "rule import inspection has warnings; the Agent acting as DM must "
                "review them before setting acknowledge_warnings=true",
                missing=("rule_import_warning_acknowledgement",),
                ruling_kind="source_or_scene_fact",
            )
        values = dict(job.payload)
        embedder, vectors = storage.dense_components()
        result = rules.ingest_path(
            system_id=DND5E.id,
            path=storage.artifact_rulebook_path(job.artifact),
            source_key=str(values["source_key"]),
            title=str(values["title"]),
            locale=str(values.get("locale") or "en"),
            edition=str(values["edition"]),
            publication_id=str(values.get("publication_id") or ""),
            version=str(values.get("version") or ""),
            authority=str(values.get("authority") or "supplement"),
            embedder=embedder,
            vector_store=vectors,
            **rule_document_options(job.artifact_checksum),
        )
        source = rules.source(result.source_id)
        updated = import_jobs.record_result(
            job_id,
            {"ingest": asdict(result), "source": source},
            state="extracted",
            source_id=result.source_id,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda updated_job: {
                    "job": import_job_view(updated_job),
                    "source": source,
                    **asdict(result),
                },
            ),
        )
        return {"job": import_job_view(updated), "source": source, **asdict(result)}

    def validate_rule_candidate_execution_evidence(
        job: Any,
        decisions: list[dict[str, Any]],
    ) -> None:
        """Prove reviewed plans and clauses quote their exact indexed chunks."""

        if job.kind != "rulebook" or not job.source_id:
            return
        candidates = {
            str(candidate.get("id") or ""): dict(candidate)
            for candidate in job.candidates
        }
        chunks = {
            str(chunk.get("id") or ""): dict(chunk)
            for chunk in rules.source_chunks(job.source_id)
        }
        for decision in decisions:
            if decision.get("review_status") != "accepted":
                continue
            candidate_id = str(decision.get("id") or "")
            candidate = candidates.get(candidate_id)
            if candidate is None:
                continue
            artifact = dict(
                decision.get("artifact")
                if "artifact" in decision
                else candidate.get("artifact") or {}
            )
            card = dict(artifact.get("card") or {})
            raw_plan = artifact.get(
                "resolution_plan",
                card.get("resolution_plan"),
            )
            raw_plans = artifact.get(
                "resolution_plans",
                card.get("resolution_plans"),
            )
            plans = (
                [raw_plan]
                if raw_plan is not None
                else list(raw_plans or [])
            )
            citations: list[tuple[str, Any]] = [
                (
                    f"candidate {candidate_id} resolution plan",
                    citation,
                )
                for plan in plans
                if isinstance(plan, dict)
                for citation in list(plan.get("citations") or [])
            ]
            raw_clauses = artifact.get(
                "rule_clauses",
                card.get("rule_clauses"),
            )
            citations.extend(
                (
                    f"candidate {candidate_id} rule clause "
                    f"{str(clause.get('id') or '')}",
                    citation,
                )
                for clause in list(raw_clauses or [])
                if isinstance(clause, dict)
                for citation in list(clause.get("source_citations") or [])
            )
            allowed_chunks = {
                str(chunk_id)
                for chunk_id in candidate.get("source_chunk_ids") or []
            }
            for field, citation in citations:
                if not isinstance(citation, dict):
                    raise ValueError(f"{field} citation must be an object")
                source_ref = citation.get("source_ref")
                if not isinstance(source_ref, dict):
                    raise ValueError(f"{field} citation needs source_ref")
                chunk_id = str(source_ref.get("chunk_id") or "")
                if chunk_id not in allowed_chunks or chunk_id not in chunks:
                    raise ValueError(
                        f"{field} citation must use one of the candidate's "
                        "indexed chunks"
                    )
                canonical = rules.citation(
                    chunk_id,
                    source_id=job.source_id,
                )
                if str(citation.get("source") or "") != str(
                    canonical["source"]
                ):
                    raise ValueError(
                        f"{field} citation source does not match its indexed chunk"
                    )
                for key in (
                    "source_id",
                    "source_key",
                    "source_checksum",
                ):
                    if key in source_ref and str(source_ref[key]) != str(
                        canonical[key]
                    ):
                        raise ValueError(
                            f"{field} citation {key} does not match its "
                            "indexed chunk"
                        )
                excerpt = _normalize_source_evidence_text(
                    citation.get("source_excerpt")
                )
                content = _normalize_source_evidence_text(
                    chunks[chunk_id].get("content")
                )
                if len(excerpt) < 10 or excerpt not in content:
                    raise ValueError(
                        f"{field} source_excerpt is not exact text from "
                        "its indexed chunk"
                    )

    @mcp.tool()
    def rule_content_candidates_extract(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Extract conservative source-linked D&D content for Agent-as-DM review."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for candidate extraction")
        job = require_import_job(campaign_id, job_id, "rulebook")
        if not job.source_id:
            raise ValueError("rule import job must be indexed before candidate extraction")
        payload = {"job_id": job_id, "operation": "extract_candidates"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        source = rules.source(job.source_id)
        candidates = extract_content_candidates(
            rules.source_chunks(job.source_id),
            source_title=str(source.get("title") or ""),
        )
        for candidate in candidates:
            candidate["source_citations"] = [
                rules.citation(chunk_id, source_id=job.source_id)
                for chunk_id in candidate["source_chunk_ids"]
            ]
        updated = import_jobs.set_candidates(
            job_id,
            candidates,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "candidates": [import_candidate_view(item) for item in result.candidates],
                },
            ),
        )
        candidate_views = [import_candidate_view(item) for item in updated.candidates]
        return {"job": import_job_view(updated), "candidates": candidate_views}

    @mcp.tool()
    def import_job_review_candidates(
        campaign_id: str,
        job_id: str,
        decisions: list[dict[str, Any]],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Accept, reject, or complete extracted content cards before pack compilation."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for candidate review")
        job = require_import_job(campaign_id, job_id)
        payload = {"job_id": job_id, "operation": "review", "decisions": decisions}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        validate_rule_candidate_execution_evidence(job, decisions)
        updated = import_jobs.review_candidates(
            job_id,
            decisions,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "candidates": [import_candidate_view(item) for item in result.candidates],
                },
            ),
        )
        candidate_views = [import_candidate_view(item) for item in updated.candidates]
        return {"job": import_job_view(updated), "candidates": candidate_views}

    @mcp.tool()
    def campaign_member_grant(
        campaign_id: str,
        principal_id: str,
        role: str = "player",
        by_principal_id: str | None = None,
    ) -> dict[str, Any]:
        """Grant DM/player/observer campaign access; caller role is resolved server-side."""
        caller = by_principal_id or LOCAL_SYSTEM_PRINCIPAL_ID
        access.require_campaign(campaign_id, caller, roles=CAMPAIGN_DM_ROLES)
        access.ensure_principal(principal_id, platform="mcp", external_id=principal_id)
        return asdict(access.grant_campaign(campaign_id, principal_id, role=role))

    @mcp.tool()
    def actor_grant(
        campaign_id: str,
        principal_id: str,
        actor_id: str,
        can_control: bool = False,
        can_view_private: bool = False,
        by_principal_id: str | None = None,
    ) -> dict[str, Any]:
        """Grant an explicit PC/NPC control and private-sheet view permission."""
        caller = by_principal_id or LOCAL_SYSTEM_PRINCIPAL_ID
        access.require_campaign(campaign_id, caller, roles=CAMPAIGN_DM_ROLES)
        access.ensure_principal(principal_id, platform="mcp", external_id=principal_id)
