    @mcp.tool()
    def campaign_rule_profile_get(
        campaign_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any] | None:
        """Read the campaign edition/publication profile and exact branch-local pack lock."""
        access.require_campaign(campaign_id, principal_id)
        profile = rule_profiles.get(campaign_id)
        campaign = campaigns.get(campaign_id)
        try:
            effective = effective_ruleset_view(campaign_id)
            effective_error = None
        except RulePackError as error:
            effective = None
            effective_error = str(error)
        return {
            "profile": asdict(profile) if profile else None,
            "activations": [asdict(item) for item in rule_packs.activations(campaign_id)],
            "effective": effective,
            "effective_error": effective_error,
            "campaign_revision": campaign.revision,
        }

    @mcp.tool()
    def campaign_rule_profile_set(
        campaign_id: str,
        edition: str,
        locale: str = "en",
        publications: list[str] | None = None,
        options: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Set non-executable edition/publication metadata outside active combat."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        edition = normalize_dnd_edition(edition)
        payload = {
            "edition": edition,
            "locale": locale,
            "publications": publications or [],
            "options": options or {},
        }
        scope = f"campaign-rule-profile:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        rule_packs.assert_edition_compatible(campaign_id, edition)
        rule_profiles.set(
            campaign_id,
            edition=edition,
            locale=locale,
            publications=publications,
            options=profile_options_with_core_lock(edition, options),
            expected_campaign_revision=expected_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "profile": asdict(result["profile"]),
                    "campaign_revision": result["campaign_revision"],
                },
            ),
        )
        committed = idempotency.lookup(scope, str(idempotency_key), payload)
        assert committed is not None and committed.response is not None
        return committed.response

    @mcp.tool()
    def campaign_core_relock(
        campaign_id: str,
        expected_core_fingerprint: str,
        reason: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        expected_revision: int | None = None,
        expected_head_snapshot_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Explicitly adopt the current built-in Core after a checkpointed runtime upgrade."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        if not expected_head_snapshot_id:
            raise ValueError("expected_head_snapshot_id is required for a Core relock")
        normalized_reason = str(reason or "").strip()
        if not normalized_reason:
            raise ValueError("reason is required for a Core relock")
        if len(normalized_reason) > 500:
            raise ValueError("Core relock reason exceeds 500 characters")
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        payload = {
            "expected_core_fingerprint": expected_core_fingerprint,
            "reason": normalized_reason,
            "branch_id": resolved_branch_id,
            "expected_head_snapshot_id": expected_head_snapshot_id,
        }
        scope = f"campaign-core-relock:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        branch = branches.current(campaign_id)
        if branch.id != resolved_branch_id or branch.head_snapshot_id != expected_head_snapshot_id:
            raise ValueError("current branch head changed before Core relock")
        profile = rule_profiles.get(campaign_id)
        if profile is None:
            raise RulePackError("campaign has no rule profile to relock")
        options = dict(profile.options or {})
        previous = dict(options.get("_core_rule_pack_lock") or {})
        if previous.get("fingerprint") != expected_core_fingerprint:
            raise ValueError("expected_core_fingerprint does not match the campaign lock")
        latest = get_core_rule_pack(profile.edition)
        user_options = {
            key: value for key, value in options.items() if key != "_core_rule_pack_lock"
        }

        def relock_response(result: dict[str, Any]) -> dict[str, Any]:
            return {
                "status": "relocked",
                "reason": normalized_reason,
                "previous_core_pack": previous,
                "core_pack": {
                    "id": latest.id,
                    "version": latest.version,
                    "edition": latest.edition,
                    "fingerprint": latest.fingerprint,
                },
                "profile": asdict(result["profile"]),
                "branch_id": resolved_branch_id,
                "checkpoint_snapshot_id": expected_head_snapshot_id,
                "campaign_revision": result["campaign_revision"],
            }

        rule_profiles.set(
            campaign_id,
            edition=profile.edition,
            locale=profile.locale,
            publications=list(profile.publications),
            options=profile_options_with_core_lock(profile.edition, user_options),
            expected_campaign_revision=expected_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=relock_response,
            ),
        )
        committed = idempotency.lookup(scope, str(idempotency_key), payload)
        assert committed is not None and committed.response is not None
        return committed.response

    @mcp.tool()
    def campaign_rule_pack_set(
        campaign_id: str,
        pack_id: str,
        version: str,
        enabled: bool = True,
        options: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Explicitly pin and enable/disable an installed pack on one campaign branch."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        payload = {
            "pack_id": pack_id,
            "version": version,
            "enabled": enabled,
            "options": options or {},
            "branch_id": resolved_branch_id,
        }
        scope = f"campaign-rule-pack-set:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        profile = rule_profiles.get(campaign_id)
        if enabled:
            if profile is None:
                raise RulesetUnavailableError(
                    "campaign must lock an edition before enabling a rule pack"
                )
            installed_pack = rule_packs.get_version(pack_id, version)
            validate_active_native_mechanic_contract(
                installed_pack.manifest,
                edition=profile.edition,
            )

        def activation_response(result: dict[str, Any]) -> dict[str, Any]:
            return {
                "activation": asdict(result["activation"]),
                "effective": effective_ruleset_view_from(
                    result["effective"],
                    profile,
                ),
                "campaign_revision": int(result["campaign_revision"]),
            }

        rule_packs.set_activation(
            campaign_id,
            pack_id=pack_id,
            version=version,
            enabled=enabled,
            options=options,
            branch_id=resolved_branch_id,
            expected_campaign_revision=expected_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=activation_response,
            ),
        )
        committed = idempotency.lookup(scope, str(idempotency_key), payload)
        assert committed is not None and committed.response is not None
        return committed.response

    @mcp.tool()
    def campaign_rule_pack_remove(
        campaign_id: str,
        pack_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Remove a future branch-local activation while preserving historical receipts."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        payload = {"pack_id": pack_id, "branch_id": resolved_branch_id}
        scope = f"campaign-rule-pack-remove:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        profile = rule_profiles.get(campaign_id)

        def removal_response(result: dict[str, Any]) -> dict[str, Any]:
            return {
                "effective": effective_ruleset_view_from(
                    result["effective"],
                    profile,
                ),
                "campaign_revision": int(result["campaign_revision"]),
            }

        rule_packs.remove_activation(
            campaign_id,
            pack_id,
            branch_id=resolved_branch_id,
            expected_campaign_revision=expected_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=removal_response,
            ),
        )
        committed = idempotency.lookup(scope, str(idempotency_key), payload)
        assert committed is not None and committed.response is not None
        return committed.response

    @mcp.tool()
    def campaign_rules_explain(
        campaign_id: str,
        event: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
    ) -> dict[str, Any]:
        """Explain the exact lock, fingerprint, and source-cited mechanics used for settlement."""
        access.require_campaign(campaign_id, principal_id)
        effective = rule_packs.effective_ruleset(campaign_id, branch_id=branch_id)
        context = effective_rule_context(campaign_id, branch_id=branch_id)
        mechanics = [
            asdict(item) for item in context.mechanics if event is None or item.event == event
        ]
        return {
            "campaign_id": campaign_id,
            "branch_id": effective.branch_id,
            "fingerprint": context.fingerprint,
            "core_pack": {
                "id": context.core_pack.id,
                "version": context.core_pack.version,
                "edition": context.core_pack.edition,
                "fingerprint": context.core_pack.fingerprint,
            },
            "core_boundaries": [asdict(item) for item in context.core_pack.boundaries],
            "lock": list(effective.lock),
            "mechanics": mechanics,
            "coverage": sorted({item.event for item in context.mechanics}),
        }

    @mcp.tool()
    def campaign_rule_receipts(
        campaign_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        mechanic_id: str | None = None,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        """Read immutable historical rule evidence for committed settlements."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        resolved_branch_id = readable_branch(campaign_id, branch_id, principal_id)
        return [
            asdict(item)
            for item in rule_receipts.list(
                campaign_id,
                branch_id=resolved_branch_id,
                mechanic_id=mechanic_id,
                limit=limit,
            )
        ]

    def available_content_artifacts(
        campaign_id: str, *, kind: str | None = None, branch_id: str | None = None
    ) -> list[tuple[str, str, dict[str, Any]]]:
        profile = rule_profiles.get(campaign_id)
        values: list[tuple[str, str, dict[str, Any]]] = []
        if profile and profile.edition == "2014":
            try:
                core = rule_packs.get_version(CORE_CONTENT_PACK_ID, CORE_CONTENT_PACK_VERSION)
            except LookupError:
                # A headless server may intentionally run without the bundled
                # skill repository. Enabled user packs must remain usable.
                core = None
            if core is not None:
                values.extend((core.pack_id, core.version, dict(item)) for item in core.artifacts)
            try:
                standard = rule_packs.get_version(
                    STANDARD_2014_CONTENT_PACK_ID,
                    STANDARD_2014_CONTENT_PACK_VERSION,
                )
            except LookupError:
                standard = None
            if standard is not None:
                values.extend(
                    (standard.pack_id, standard.version, dict(item))
                    for item in standard.artifacts
                )
        for activation in rule_packs.activations(campaign_id, branch_id=branch_id):
            if not activation.enabled:
                continue
            pack = rule_packs.get_version(activation.pack_id, activation.version)
            values.extend((pack.pack_id, pack.version, dict(item)) for item in pack.artifacts)
        return [item for item in values if kind is None or item[2].get("kind") == kind]

    def hydrate_class_prepared_spell_cards(
        campaign_id: str,
        sheet: dict[str, Any],
        *,
        spell_ids: list[str],
        branch_id: str,
    ) -> dict[str, Any]:
        """Materialize legal catalog choices before strict prepared-list validation."""
        value = deepcopy(sheet)
        preparation_mode = str(
            value.get("spellcasting", {}).get("preparation", {}).get("mode") or "known"
        )
        if preparation_mode != "prepared":
            return {"sheet": value, "materialized_spell_ids": []}

        existing = {
            str(item.get("id") or "")
            for item in value.get("content", {}).get("spells", [])
        }
        requested = list(dict.fromkeys(str(item).strip() for item in spell_ids))
        missing = [item for item in requested if item and item not in existing]
        if not missing:
            return {"sheet": value, "materialized_spell_ids": []}

        catalog: dict[str, list[tuple[str, str, dict[str, Any]]]] = {}
        for candidate in available_content_artifacts(
            campaign_id,
            kind="spell",
            branch_id=branch_id,
        ):
            catalog.setdefault(str(candidate[2].get("id") or ""), []).append(candidate)

        class_names = list(
            dict.fromkeys(
                str(item.get("name") or "").strip()
                for item in value.get("progression", {}).get("classes", [])
                if str(item.get("name") or "").strip()
            )
        )
        materialized: list[str] = []
        for spell_id in missing:
            matches = catalog.get(spell_id, [])
            if not matches:
                raise CombatEngineError(
                    f"prepared spell is not available from the campaign's active "
                    f"content packs: {spell_id}"
                )
            if len(matches) != 1:
                raise CombatEngineError(
                    f"prepared spell resolves to multiple active content artifacts: {spell_id}"
                )
            pack_id, version, artifact = matches[0]
            if str(artifact.get("application_state") or "selection_ready") != "selection_ready":
                raise CombatEngineError(
                    f"prepared spell requires reviewed selection-ready content: {spell_id}"
                )
            card = deepcopy(dict(artifact.get("card") or {}))
            eligible_sources: list[str] = []
            eligibility_errors: list[CombatEngineError] = []
            for class_name in class_names:
                try:
                    eligible_sources.append(
                        validate_spell_grant(
                            value,
                            card,
                            source_class=class_name,
                        )
                    )
                except CombatEngineError as error:
                    eligibility_errors.append(error)
            eligible_sources = list(dict.fromkeys(eligible_sources))
            if not eligible_sources:
                if len(class_names) == 1 and eligibility_errors:
                    raise eligibility_errors[0]
                raise CombatEngineError(
                    f"prepared spell has no legal recorded source class: {spell_id}"
                )
            if len(eligible_sources) != 1:
                raise CombatEngineError(
                    f"prepared spell needs one unambiguous source class: {spell_id}"
                )
            source_class = eligible_sources[0]
            card.pop("classes", None)
            card["grant"] = {
                "source_type": "class",
                "source_key": source_class,
                "method": "class_prepared",
            }
            access_state = card.setdefault("access", {})
            access_state["known"] = False
            access_state["prepared"] = False
            card.update(
                id=spell_id,
                pack_id=pack_id,
                pack_version=version,
                rule_refs=list(artifact.get("rule_refs") or []),
                mechanic_refs=list(artifact.get("mechanic_refs") or []),
            )
            value.setdefault("content", {}).setdefault("spells", []).append(card)
            materialized.append(spell_id)
        return {"sheet": value, "materialized_spell_ids": materialized}

    def hydrate_statblock_spellcasting(
        campaign_id: str,
        parsed: Any,
        *,
        source_key: str,
        rule_refs: list[str],
    ) -> tuple[dict[str, Any], list[str]]:
        """Bind a parsed statblock spell list to exact active content artifacts."""
        sheet = deepcopy(parsed.sheet)
        spellcasting = deepcopy(parsed.spellcasting)
        if not isinstance(spellcasting, dict):
            return sheet, []

        sheet["spellcasting"]["ability"] = spellcasting["ability"]
        sheet["spellcasting"]["attack_bonus_override"] = spellcasting.get("attack_bonus")
        sheet["spellcasting"]["save_dc_override"] = spellcasting.get("save_dc")
        sheet["spellcasting"]["spell_slots"] = {
            str(level): {
                "label": f"Level {level} spell slots",
                "value": int(count),
                "max": int(count),
                "recovers_on": "long_rest",
                "source_key": source_key,
                "slot_level": int(level),
            }
            for level, count in dict(spellcasting.get("slots") or {}).items()
        }

        candidates = available_content_artifacts(campaign_id, kind="spell")
        prepared_ids: list[str] = []
        warnings: list[str] = []
        innate = bool(spellcasting.get("innate"))
        for specification in spellcasting.get("spells", []):
            name = str(specification.get("name") or "").strip()
            raw_level = specification.get("level")
            level = int(raw_level) if raw_level is not None else None
            exact = [
                item
                for item in candidates
                if str(dict(item[2].get("card") or {}).get("name") or "").casefold()
                == name.casefold()
                and (
                    level is None
                    or int(dict(item[2].get("card") or {}).get("level", 0) or 0)
                    == level
                )
            ]
            if len(exact) == 1:
                pack_id, version, artifact = exact[0]
                card = deepcopy(dict(artifact.get("card") or {}))
                card.pop("classes", None)
                card.update(
                    {
                        "id": str(artifact["id"]),
                        "pack_id": pack_id,
                        "pack_version": version,
                        "rule_refs": list(artifact.get("rule_refs") or []),
                        "mechanic_refs": list(artifact.get("mechanic_refs") or []),
                    }
                )
                action_description = str(specification.get("action_description") or "").strip()
                if action_description and isinstance(card.get("resolution"), dict):
                    card = overlay_spell_attack_card(card, action_description)
            elif len(exact) > 1:
                warnings.append(
                    f"{name}: multiple active spell artifacts match the statblock entry"
                )
                continue
            else:
                action_description = str(specification.get("action_description") or "").strip()
                if not action_description:
                    warnings.append(
                        f"{name}: no active spell artifact or complete statblock action exists"
                    )
                    continue
                display_name = re.sub(
                    r"\s*\([^)]*\)\s*$",
                    "",
                    str(specification.get("action_name") or name),
                ).strip()
                slug = ascii_slug(name)
                range_match = re.search(
                    r"(?i)range\s+(\d+)(?:\s*/\s*(\d+))?\s*ft",
                    action_description,
                )
                normal_range = int(range_match.group(1)) if range_match else 0
                long_range = int(range_match.group(2) or 0) if range_match else 0
                card = {
                    "id": f"{source_key}.spell.{slug}",
                    "source_key": source_key,
                    "name": display_name,
                    "level": int(level or 0),
                    "definition": {
                        "casting_time": "1 action",
                        "range": {
                            "kind": "distance" if range_match else "special",
                            "normal_ft": normal_range,
                            "long_ft": long_range,
                        },
                        "duration": {"kind": "instantaneous"},
                        "components": {},
                        "effect": action_description,
                    },
                    "custom_definition": {
                        "source": source_key,
                        "component_details": "not_repeated_in_statblock",
                    },
                    "ruling_requirements": [
                        _ruling_requirement(
                            "Confirm the statblock spell's omitted component details "
                            "from available source and scene facts.",
                            "source_or_scene_fact",
                        ),
                        _ruling_requirement(
                            "Adjudicate the source-described spell effect.",
                            "generic_spell_effect",
                        ),
                    ],
                    "notes": (
                        "Source-bound statblock spell action. Component legality and "
                        "effect settlement return to Agent-as-DM adjudication."
                    ),
                    "pack_id": "",
                    "pack_version": "",
                    "rule_refs": list(rule_refs),
                    "mechanic_refs": [],
                }
                resolution = spell_attack_action_resolution(action_description)
                if resolution is not None:
                    card["resolution"] = resolution
                    card["mechanic_refs"] = [SPELL_RESOLUTION_MECHANIC_ID]
                    card["notes"] = (
                        "Source-bound statblock spell attack. Component legality still "
                        "returns to Agent-as-DM adjudication."
                    )
                    card["ruling_requirements"] = card["ruling_requirements"][:1]
                    warnings.append(
                        f"{display_name}: source-bound statblock spell requires component ruling"
                    )
                else:
                    warnings.append(
                        f"{display_name}: source-bound statblock spell requires component "
                        "and effect ruling"
                    )

            card["grant"] = {
                "source_type": "statblock",
                "source_key": source_key,
                "method": "innate" if innate else "known",
            }
            card["access"] = {
                "known": True,
                "prepared": True,
                "always_prepared": True,
                "in_spellbook": False,
                "ritual_available": False,
                "at_will": bool(specification.get("at_will", False)),
            }
            if innate:
                custom_definition = dict(card.get("custom_definition") or {})
                source_name = str(specification.get("source_name") or name).strip()
                source_qualifier = str(
                    specification.get("source_qualifier") or ""
                ).strip()
                custom_definition.update(
                    {
                        "statblock_source_name": source_name,
                        "innate_spellcasting": True,
                    }
                )
                if source_qualifier:
                    custom_definition["statblock_source_qualifier"] = (
                        source_qualifier
                    )
                    requirements = list(card.get("ruling_requirements") or [])
                    requirements.append(
                        _ruling_requirement(
                            "Apply the statblock spell qualifier exactly: "
                            f"{source_qualifier}.",
                            "source_or_scene_fact",
                        )
                    )
                    card["ruling_requirements"] = requirements
                if spellcasting.get("no_material_components"):
                    components = dict(
                        dict(card.get("definition") or {}).get("components") or {}
                    )
                    components.update(
                        {
                            "material": False,
                            "material_description": "",
                            "material_cost_cp": 0,
                            "consumed": False,
                        }
                    )
                    card.setdefault("definition", {})["components"] = components
                    custom_definition["statblock_omits_material_components"] = True
                uses_per_day = specification.get("uses_per_day")
                if uses_per_day is not None:
                    independent = bool(
                        specification.get("uses_are_independent")
                    )
                    usage_group = str(
                        specification.get("usage_group") or "daily"
                    ).strip()
                    resource_key = (
                        f"innate_spell:{card['id']}"
                        if independent
                        else f"innate_spell_group:{source_key}:{usage_group}"
                    )
                    custom_definition["innate_resource_key"] = resource_key
                    existing_resource = dict(
                        sheet.setdefault("resources", {}).get(resource_key) or {}
                    )
                    resource = {
                        "label": (
                            f"{card['name']} ({int(uses_per_day)}/day)"
                            if independent
                            else f"Innate spell group ({int(uses_per_day)}/day)"
                        ),
                        "value": int(uses_per_day),
                        "max": int(uses_per_day),
                        "recovers_on": "long_rest",
                        "source_key": source_key,
                    }
                    if existing_resource and existing_resource != resource:
                        raise ValueError(
                            "innate spell usage group has conflicting resource limits"
                        )
                    sheet["resources"][resource_key] = resource
                card["custom_definition"] = custom_definition
            sheet["content"]["spells"].append(card)
            prepared_ids.append(str(card["id"]))

        sheet["spellcasting"]["preparation"] = {
            "mode": "known",
            "max_prepared": len(prepared_ids),
            "changes_on": "manual",
            "selected_spell_ids": prepared_ids,
        }
        return validate_character_sheet(sheet), warnings

    def hydrate_statblock_variant_spells(
        campaign_id: str,
        sheet: dict[str, Any],
        variant: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Hydrate source-cited replacement spells from active content.

        Public variants supply only canonical spell ids. They cannot inject
        arbitrary spell cards; every replacement target must resolve exactly
        once in the campaign's active D&D content.
        """

        if variant is None or "spell_replacements" not in variant:
            return sheet
        replacements = variant["spell_replacements"]
        if not isinstance(replacements, list) or not replacements:
            raise ValueError("spell_replacements must be a non-empty list")
        add_ids: list[str] = []
        for index, raw in enumerate(replacements):
            if not isinstance(raw, dict):
                raise ValueError(f"spell_replacements[{index}] must be an object")
            add_spell_id = str(raw.get("add_spell_id") or "").strip()
            if not add_spell_id:
                raise ValueError(f"spell_replacements[{index}].add_spell_id is required")
            add_ids.append(add_spell_id)
        if len(add_ids) != len(set(add_ids)):
            raise ValueError("spell replacement targets must be unique")

        hydrated = deepcopy(sheet)
        spells = list(dict(hydrated.get("content") or {}).get("spells") or [])
        existing_ids = {str(item.get("id") or "") for item in spells}
        artifacts = available_content_artifacts(campaign_id, kind="spell")
        variant_source = f"variant:{statblock_variant_source_label(variant)}"
        for add_spell_id in add_ids:
            if add_spell_id in existing_ids:
                continue
            matches = [item for item in artifacts if str(item[2].get("id") or "") == add_spell_id]
            if len(matches) != 1:
                raise ValueError(
                    "statblock replacement spell must resolve exactly once in active "
                    f"content: {add_spell_id}"
                )
            pack_id, version, artifact = matches[0]
            card = deepcopy(dict(artifact.get("card") or {}))
            card.pop("classes", None)
            card.update(
                {
                    "id": str(artifact["id"]),
                    "pack_id": pack_id,
                    "pack_version": version,
                    "rule_refs": list(artifact.get("rule_refs") or []),
                    "mechanic_refs": list(artifact.get("mechanic_refs") or []),
                    "grant": {
                        "source_type": "statblock_variant",
                        "source_key": variant_source,
                        "method": "known",
                    },
                    "access": {
                        "known": True,
                        "prepared": False,
                        "always_prepared": False,
                        "in_spellbook": False,
                        "ritual_available": False,
                        "at_will": False,
                    },
                }
            )
            spells.append(card)
            existing_ids.add(add_spell_id)
        hydrated["content"]["spells"] = spells
        return validate_character_sheet(hydrated)

    def hydrate_magic_item_spell_artifacts(
        campaign_id: str,
        item: dict[str, Any],
    ) -> dict[str, Any]:
        """Bind declared magic-item spell ids to exact active catalog cards."""
        hydrated = deepcopy(item)
        mechanics = deepcopy(dict(hydrated.get("mechanics") or {}))
        spellcasting = mechanics.get("spellcasting")
        if spellcasting is None:
            return hydrated
        if hydrated.get("kind") != "magic_item":
            raise ValueError("item spellcasting is supported only for kind=magic_item")
        if not str(hydrated.get("source_key") or "").strip():
            raise ValueError("magic item spellcasting requires a source_key")
        if not isinstance(spellcasting, dict):
            raise ValueError("magic item mechanics.spellcasting must be an object")
        allowed_spellcasting = {
            "requires_attunement",
            "requires_class_spell_list",
            "components_required",
            "spells",
        }
        unexpected = sorted(set(spellcasting) - allowed_spellcasting)
        if unexpected:
            raise ValueError(f"magic item spellcasting has unsupported fields: {unexpected}")
        raw_spells = spellcasting.get("spells")
        if not isinstance(raw_spells, list) or not raw_spells:
            raise ValueError("magic item spellcasting requires at least one spell")
        available = available_content_artifacts(campaign_id, kind="spell")
        resolved: list[dict[str, Any]] = []
        seen: set[str] = set()
        for index, specification in enumerate(raw_spells):
            if not isinstance(specification, dict):
                raise ValueError(f"magic item spellcasting.spells[{index}] must be an object")
            allowed_specification = {"artifact_id", "charge_cost", "casting_time"}
            unknown = sorted(set(specification) - allowed_specification)
            if unknown:
                raise ValueError(
                    f"magic item spellcasting.spells[{index}] has unsupported fields: {unknown}"
                )
            artifact_id = str(specification.get("artifact_id") or "").strip()
            if not artifact_id or artifact_id in seen:
                raise ValueError("magic item spell artifact ids must be present and unique")
            seen.add(artifact_id)
            charge_cost = specification.get("charge_cost")
            if (
                isinstance(charge_cost, bool)
                or not isinstance(charge_cost, int)
                or charge_cost <= 0
            ):
                raise ValueError("magic item spell charge_cost must be a positive integer")
            matches = [entry for entry in available if str(entry[2].get("id")) == artifact_id]
            if len(matches) != 1:
                raise ValueError(
                    f"magic item spell artifact must resolve exactly once: {artifact_id}"
                )
            pack_id, version, artifact = matches[0]
            card = deepcopy(dict(artifact.get("card") or {}))
            card.update(
                {
                    "id": artifact_id,
                    "pack_id": pack_id,
                    "pack_version": version,
                    "rule_refs": list(artifact.get("rule_refs") or []),
                    "mechanic_refs": list(artifact.get("mechanic_refs") or []),
                }
            )
            casting_time = str(specification.get("casting_time") or "").strip()
            resolved.append(
                {
                    "artifact_id": artifact_id,
                    "charge_cost": charge_cost,
                    **({"casting_time": casting_time} if casting_time else {}),
                    "card": card,
                }
            )
        charges = dict(hydrated.get("charges") or {})
        maximum = charges.get("max")
        if isinstance(maximum, bool) or not isinstance(maximum, int) or maximum <= 0:
            raise ValueError("magic item spellcasting requires a positive charges.max")
        if max(item["charge_cost"] for item in resolved) > maximum:
            raise ValueError("magic item spell charge_cost exceeds charges.max")
        mechanics["spellcasting"] = {
            "requires_attunement": bool(spellcasting.get("requires_attunement")),
            "requires_class_spell_list": bool(spellcasting.get("requires_class_spell_list")),
            "components_required": bool(spellcasting.get("components_required", True)),
            "spells": resolved,
        }
        hydrated["mechanics"] = mechanics
        return hydrated

    def settle_magic_item_last_charge(
        applied: dict[str, Any],
        *,
        source_item_id: str | None,
        rules: ResolutionContext,
    ) -> dict[str, Any]:
        """Resolve a source-bound last-charge destruction check in the same mutation."""
        if not source_item_id or not applied.get("last_charge_rule"):
            return applied
        last_charge_rule = dict(applied["last_charge_rule"])
        dice = asdict(roll(str(last_charge_rule["formula"])))
        resolution = resolve_magic_item_last_charge(
            applied["sheet"],
            source_item_id=source_item_id,
            rolled_total=int(dice["total"]),
        )
        result = dict(applied)
        result["sheet"] = resolution["sheet"]
        result["last_charge_resolution"] = {
            key: value for key, value in resolution.items() if key not in {"sheet", "rule_receipts"}
        } | {"roll": dice}
        result["rule_receipts"] = [
            *list(applied.get("rule_receipts") or []),
            *core_receipts(
                rules,
                [CORE_MAGIC_ITEM_LAST_CHARGE_MECHANIC_ID],
                "spell.magic_item.last_charge",
            ),
        ]
        return result

    def refresh_level_unlocked_subclass_spells(
        campaign_id: str,
        sheet: dict[str, Any],
        *,
        class_name: str,
        branch_id: str,
    ) -> list[dict[str, Any]]:
        """Materialize always-prepared subclass spells unlocked by the new class level."""
        target_class = next(
            item
            for item in sheet["progression"]["classes"]
            if str(item.get("name") or "").casefold() == class_name.casefold()
        )
        subclass_name = str(target_class.get("subclass") or "")
        if not subclass_name:
            return []

        def exact_recorded_card(
            record: dict[str, Any],
            *,
            required: bool = True,
        ) -> dict[str, Any] | None:
            artifact_id = str(record.get("artifact_id") or record.get("id") or "")
            pack_id = str(record.get("pack_id") or "")
            version = str(record.get("pack_version") or "")
            if not artifact_id or not pack_id or not version:
                raise ValueError(
                    "recorded subclass content must include artifact id, pack id, and pack version"
                )
            try:
                pack = rule_packs.get_version(pack_id, version)
            except LookupError as error:
                raise RulesetUnavailableError(
                    f"recorded subclass content pack is unavailable: {pack_id}@{version}"
                ) from error
            artifact = next(
                (item for item in pack.artifacts if str(item.get("id") or "") == artifact_id),
                None,
            )
            if artifact is None:
                if not required:
                    return None
                raise RulesetUnavailableError(
                    f"recorded subclass content is unavailable: "
                    f"{artifact_id} in {pack_id}@{version}"
                )
            return dict(artifact.get("card") or {})

        grant_sources: list[tuple[str, list[dict[str, Any]]]] = []
        recorded_subclass = next(
            (
                item
                for item in sheet.get("content", {}).get("selections", [])
                if str(item.get("kind") or "") == "subclass"
                and str(item.get("name") or "").casefold() == subclass_name.casefold()
            ),
            None,
        )
        if recorded_subclass is not None:
            subclass_card = exact_recorded_card(recorded_subclass)
            assert subclass_card is not None
            if str(subclass_card.get("class_name") or "").casefold() != class_name.casefold():
                raise ValueError("recorded subclass does not belong to the advanced class")
            grant_sources.append(
                (
                    subclass_name,
                    list(subclass_card.get("always_prepared_spells") or []),
                )
            )
        for feature_record in sheet.get("content", {}).get("features", []):
            if not feature_record.get("pack_id") or not feature_record.get("pack_version"):
                continue
            feature_card = exact_recorded_card(feature_record, required=False)
            if feature_card is None:
                continue
            if (
                str(feature_card.get("class_name") or "").casefold() != class_name.casefold()
                or str(feature_card.get("subclass_name") or "").casefold()
                != subclass_name.casefold()
            ):
                continue
            spell_options = dict(feature_card.get("always_prepared_spell_options") or {})
            if not spell_options:
                continue
            choices = dict(feature_record.get("choices") or {})
            if not choices:
                grants = list(feature_record.get("advancement_grants") or [])
                if grants:
                    choices = dict(grants[-1].get("choices") or {})
            option = str(choices.get("option") or "")
            if option not in spell_options:
                raise ValueError("recorded subclass spell option is missing or unavailable")
            grant_sources.append((subclass_name, list(spell_options[option])))

        candidates = available_content_artifacts(campaign_id, branch_id=branch_id)
        class_level = int(target_class.get("level", 0) or 0)
        unlocked: list[dict[str, Any]] = []
        always_prepared_ids: set[str] = set()
        for source_name, grants in grant_sources:
            for grant in grants:
                minimum_level = int(grant.get("minimum_level", 1) or 1)
                if minimum_level > class_level:
                    continue
                spell_name = str(grant.get("name") or "").strip()
                match = next(
                    (
                        item
                        for item in candidates
                        if item[2].get("kind") == "spell"
                        and str(dict(item[2].get("card") or {}).get("name") or "").casefold()
                        == spell_name.casefold()
                    ),
                    None,
                )
                if match is None:
                    raise RulesetUnavailableError(
                        f"subclass spell is unavailable at level {class_level}: {spell_name}"
                    )
                spell_pack_id, spell_version, spell_artifact = match
                spell_id = str(spell_artifact["id"])
                always_prepared_ids.add(spell_id)
                spell_card = next(
                    (
                        item
                        for item in sheet["content"]["spells"]
                        if str(item.get("id") or "") == spell_id
                    ),
                    None,
                )
                was_always_prepared = bool(
                    spell_card and dict(spell_card.get("access") or {}).get("always_prepared")
                )
                if spell_card is None:
                    spell_card = deepcopy(dict(spell_artifact.get("card") or {}))
                    spell_card.pop("classes", None)
                    sheet["content"]["spells"].append(spell_card)
                spell_card["grant"] = {
                    "source_type": "subclass",
                    "source_key": source_name,
                    "method": "class_prepared",
                }
                spell_card.setdefault("access", {})["known"] = False
                spell_card["access"]["prepared"] = True
                spell_card["access"]["always_prepared"] = True
                spell_card.update(
                    id=spell_id,
                    pack_id=spell_pack_id,
                    pack_version=spell_version,
                    rule_refs=list(spell_artifact.get("rule_refs") or []),
                    mechanic_refs=list(spell_artifact.get("mechanic_refs") or []),
                )
                if not was_always_prepared:
                    unlocked.append(
                        {
                            "artifact_id": spell_id,
                            "name": str(spell_card.get("name") or spell_name),
                            "minimum_level": minimum_level,
                            "source_subclass": source_name,
                        }
                    )
        if always_prepared_ids:
            preparation = sheet["spellcasting"]["preparation"]
            preparation["selected_spell_ids"] = [
                spell_id
                for spell_id in preparation.get("selected_spell_ids", [])
                if spell_id not in always_prepared_ids
            ]
        return unlocked

    def level_advancement_content_context(
        campaign_id: str,
        sheet: dict[str, Any],
        *,
        class_name: str,
        new_level: int,
        branch_id: str,
    ) -> dict[str, Any]:
        """Resolve source-bound per-level modifiers and post-level catalog work."""
        candidates = available_content_artifacts(campaign_id, branch_id=branch_id)

        def exact_recorded_artifact(record: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
            artifact_id = str(record.get("artifact_id") or record.get("id") or "")
            pack_id = str(record.get("pack_id") or "")
            version = str(record.get("pack_version") or "")
            if not artifact_id or not pack_id or not version:
                raise ValueError(
                    "level-affecting content must record artifact id, pack id, and pack version"
                )
            try:
                pack = rule_packs.get_version(pack_id, version)
            except LookupError as error:
                raise RulesetUnavailableError(
                    f"recorded content pack is unavailable: {pack_id}@{version}"
                ) from error
            artifact = next(
                (item for item in pack.artifacts if str(item.get("id") or "") == artifact_id),
                None,
            )
            if artifact is None:
                embedded = next(
                    (
                        feature
                        for item in pack.artifacts
                        for feature in dict(dict(item.get("card") or {}).get("grants") or {}).get(
                            "features", []
                        )
                        if str(feature.get("id") or "") == artifact_id
                    ),
                    None,
                )
                if embedded is not None:
                    artifact = {"id": artifact_id, "kind": "feature", "card": embedded}
            if artifact is None:
                raise RulesetUnavailableError(
                    f"recorded artifact is unavailable: {artifact_id} in {pack_id}@{version}"
                )
            return pack_id, version, dict(artifact)

        hp_per_level_bonus = 0
        hp_bonus_sources: list[dict[str, Any]] = []
        for selection in sheet.get("content", {}).get("selections", []):
            artifact_id = str(selection.get("artifact_id") or "")
            if not artifact_id:
                continue
            pack_id, version, artifact = exact_recorded_artifact(selection)
            card = dict(artifact.get("card") or {})
            grants = dict(card.get("grants") or {})
            amount = int(grants.get("hp_per_level", 0) or 0)
            if amount:
                hp_per_level_bonus += amount
                hp_bonus_sources.append(
                    {
                        "artifact_id": artifact_id,
                        "pack_id": pack_id,
                        "pack_version": version,
                        "amount": amount,
                        "scope": "character_level",
                    }
                )
        feature_records = list(sheet.get("content", {}).get("features", []))
        present_features = {
            str(item.get("id") or ""): item for item in feature_records if item.get("id")
        }
        for feature in feature_records:
            artifact_id = str(feature.get("id") or "")
            if not artifact_id or not feature.get("pack_id") or not feature.get("pack_version"):
                continue
            pack_id, version, artifact = exact_recorded_artifact(feature)
            card = dict(artifact.get("card") or {})
            grants = dict(card.get("mechanical_grants") or {})
            amount = int(grants.get("hp_per_level", 0) or 0)
            if str(card.get("class_name") or "").casefold() == class_name.casefold():
                amount += int(grants.get("hp_per_class_level", 0) or 0)
            if amount:
                hp_per_level_bonus += amount
                hp_bonus_sources.append(
                    {
                        "artifact_id": artifact_id,
                        "pack_id": pack_id,
                        "pack_version": version,
                        "amount": amount,
                        "scope": "class_level",
                    }
                )

        target_class = next(
            item
            for item in sheet["progression"]["classes"]
            if str(item.get("name") or "").casefold() == class_name.casefold()
        )
        subclass_name = str(target_class.get("subclass") or "")
        feature_options: list[dict[str, Any]] = []
        subclass_options: list[dict[str, Any]] = []
        for pack_id, version, artifact in candidates:
            if str(artifact.get("application_state") or "selection_ready") != "selection_ready":
                continue
            artifact_id = str(artifact.get("id") or "")
            card = dict(artifact.get("card") or {})
            kind = str(artifact.get("kind") or "")
            declared_class = str(card.get("class_name") or "")
            minimum_level = int(card.get("minimum_level", 1) or 1)
            if declared_class.casefold() != class_name.casefold() or minimum_level > new_level:
                continue
            repeatable_levels = {
                int(value)
                for value in card.get("repeatable_selection_levels", [])
                if int(value) > 0
            }
            repeat_due = new_level in repeatable_levels
            if kind == "feature" and (artifact_id not in present_features or repeat_due):
                if str(card.get("name") or "").casefold() == "unarmored defense" and any(
                    str(item.get("name") or "").casefold() == "unarmored defense"
                    for item in feature_records
                ):
                    continue
                declared_subclass = str(card.get("subclass_name") or "")
                if declared_subclass and declared_subclass.casefold() != subclass_name.casefold():
                    continue
                requirements_by_level = dict(card.get("selection_requirements_by_level") or {})
                selection_requirements = deepcopy(
                    dict(
                        requirements_by_level.get(str(new_level))
                        or card.get("selection_requirements")
                        or {}
                    )
                )
                feature_options.append(
                    {
                        "artifact_id": artifact_id,
                        "name": str(card.get("name") or artifact_id),
                        "minimum_level": minimum_level,
                        "class_name": declared_class,
                        "subclass_name": declared_subclass,
                        "selection_requirements": selection_requirements,
                        "grant_level": new_level if repeat_due else None,
                        "pack_id": pack_id,
                        "pack_version": version,
                        "rule_refs": list(artifact.get("rule_refs") or []),
                        "_provides_resources": list(
                            dict(dict(card.get("mechanical_grants") or {}).get("resources") or {})
                        ),
                        "_requires_resource": str(card.get("resource_key") or ""),
                    }
                )
            if kind == "subclass" and not subclass_name:
                subclass_options.append(
                    {
                        "artifact_id": artifact_id,
                        "name": str(card.get("name") or artifact_id),
                        "minimum_level": minimum_level,
                        "pack_id": pack_id,
                        "pack_version": version,
                        "rule_refs": list(artifact.get("rule_refs") or []),
                    }
                )
        ordered_features: list[dict[str, Any]] = []
        pending_features = sorted(
            feature_options,
            key=lambda item: (
                item["minimum_level"],
                item["name"],
                item["artifact_id"],
            ),
        )
        provided_resources = {str(key) for key in dict(sheet.get("resources") or {})}
        while pending_features:
            pending_providers = {
                str(resource_key)
                for item in pending_features
                for resource_key in item.get("_provides_resources", [])
            }
            ready_index = next(
                (
                    index
                    for index, item in enumerate(pending_features)
                    if not str(item.get("_requires_resource") or "")
                    or str(item["_requires_resource"]) in provided_resources
                    or str(item["_requires_resource"]) not in pending_providers
                ),
                0,
            )
            selected = pending_features.pop(ready_index)
            provided_resources.update(
                str(value) for value in selected.pop("_provides_resources", [])
            )
            selected.pop("_requires_resource", None)
            ordered_features.append(selected)
        return {
            "hp_per_level_bonus": hp_per_level_bonus,
            "hp_bonus_sources": hp_bonus_sources,
            "feature_options": ordered_features,
            "subclass_options": sorted(
                subclass_options, key=lambda item: (item["name"], item["artifact_id"])
            ),
        }

    @mcp.tool()
    def content_catalog_list(
        campaign_id: str,
        kind: str | None = None,
        query: str = "",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
    ) -> list[dict[str, Any]]:
        """List core and enabled-extension character options from one uniform catalog."""
        access.require_campaign(campaign_id, principal_id)
        resolved_branch_id = readable_branch(campaign_id, branch_id, principal_id)
        lowered = query.casefold().strip()
        result = []
        for pack_id, version, artifact in available_content_artifacts(
            campaign_id, kind=kind, branch_id=resolved_branch_id
        ):
            card = dict(artifact.get("card") or {})
            name = str(card.get("name") or artifact["id"])
            if (
                lowered
                and lowered not in name.casefold()
                and lowered not in str(artifact["id"]).casefold()
            ):
                continue
            artifact_kind = str(artifact.get("kind") or "")
            selection_requirements: dict[str, Any] = {}
            if artifact_kind == "spell":
                selection_requirements = {
                    "fields": ["source_class", "method"],
                    "level": int(card.get("level", 0) or 0),
                    "eligible_classes": list(card.get("classes") or []),
                    "methods": [
                        "known",
                        "spellbook",
                        "spellbook_copy",
                        "class_prepared",
                    ],
                    "spellbook_copy_fields": [
                        "source_owner",
                        "source_item_id",
                        "payment_owner",
                        "payment",
                    ],
                }
            elif artifact_kind == "subclass":
                selection_requirements = {
                    "fields": ["target_class_name"],
                    "class_name": str(card.get("class_name") or ""),
                    "minimum_level": int(card.get("minimum_level", 1) or 1),
                }
            elif artifact_kind == "background":
                grants = dict(card.get("background_grants") or {})
                choices = dict(grants.get("choices") or {})
                selection_requirements = {
                    "fields": ["languages"] if choices.get("language_count") else [],
                    "language_count": int(choices.get("language_count", 0) or 0),
                    "skill_proficiencies": list(card.get("skill_proficiencies") or []),
                    "customizable": True,
                    "customization_fields": [
                        "custom_name",
                        "skills",
                        "languages",
                        "equipment_item_ids",
                    ],
                }
            elif artifact_kind == "feat":
                selection_requirements = {
                    "fields": [],
                    "prerequisites": deepcopy(list(card.get("prerequisites") or [])),
                }
            elif artifact_kind == "feature":
                requirements = deepcopy(dict(card.get("selection_requirements") or {}))
                selection_requirements = {
                    "fields": [requirements["field"]] if requirements.get("field") else [],
                    "class_name": str(card.get("class_name") or ""),
                    "subclass_name": str(card.get("subclass_name") or ""),
                    "minimum_level": int(card.get("minimum_level", 1) or 1),
                    "unlock_levels": [int(value) for value in card.get("unlock_levels", [])],
                    "repeatable_selection_levels": [
                        int(value) for value in card.get("repeatable_selection_levels", [])
                    ],
                    "selection_requirements_by_level": deepcopy(
                        dict(card.get("selection_requirements_by_level") or {})
                    ),
                    **requirements,
                }
            elif artifact_kind == "species":
                grants = dict(card.get("grants") or {})
                fields = []
                if int(grants.get("language_choice_count", 0) or 0):
                    fields.append("languages")
                if int(grants.get("skill_choice_count", 0) or 0):
                    fields.append("skills")
                if list(grants.get("tool_choices") or []):
                    fields.append("tools")
                if int(dict(grants.get("ability_choice") or {}).get("count", 0) or 0):
                    fields.append("abilities")
                if grants.get("cantrip_choice"):
                    fields.append("cantrip_artifact_id")
                selection_requirements = {
                    "fields": fields,
                    "base_species": str(card.get("base_species") or card.get("name") or ""),
                    "language_count": int(grants.get("language_choice_count", 0) or 0),
                    "skill_count": int(grants.get("skill_choice_count", 0) or 0),
                    "tool_options": list(grants.get("tool_choices") or []),
                    "ability_choice": deepcopy(dict(grants.get("ability_choice") or {})),
                    "cantrip_choice": deepcopy(grants.get("cantrip_choice")),
                }
            result.append(
                {
                    "id": artifact["id"],
                    "kind": artifact_kind,
                    "name": name,
                    "pack_id": pack_id,
                    "pack_version": version,
                    "rule_refs": list(artifact.get("rule_refs") or []),
                    "mechanic_refs": list(artifact.get("mechanic_refs") or []),
                    "source_citations": deepcopy(list(artifact.get("source_citations") or [])),
                    "selection_requirements": selection_requirements,
                    "application_state": str(
                        artifact.get("application_state") or "selection_ready"
                    ),
                }
            )
        return sorted(
            result,
            key=lambda item: (str(item["kind"]), str(item["name"]), str(item["id"])),
        )

    def spend_exact_wallet_payment(
        wallet: dict[str, Any], payment: Any, *, required_cp: int
    ) -> dict[str, int]:
        """Validate an explicit coin payment without inventing currency exchange or change."""
        if not isinstance(payment, dict):
            raise ValueError("spellbook copy selection.payment must be a coin object")
        unknown = set(payment) - set(DENOMINATION_CP_VALUES)
        if unknown:
            raise ValueError(f"spellbook copy payment has unknown coins: {sorted(unknown)}")
        normalized: dict[str, int] = {}
        total_cp = 0
        for denomination, multiplier in DENOMINATION_CP_VALUES.items():
            amount = payment.get(denomination, 0)
            if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
                raise ValueError("spellbook copy coin amounts must be non-negative integers")
            if amount > int(wallet.get(denomination, 0) or 0):
                raise ValueError(f"insufficient {denomination} for spellbook copy")
            normalized[denomination] = amount
            total_cp += amount * multiplier
        if total_cp != required_cp:
            raise ValueError(
                f"spellbook copy payment must equal exactly {required_cp} cp; got {total_cp} cp"
            )
        for denomination, amount in normalized.items():
            wallet[denomination] = int(wallet.get(denomination, 0) or 0) - amount
        return normalized

    def settle_spellbook_copy(
        *,
        current: Any,
        sheet: dict[str, Any],
        artifact_id: str,
        pack_id: str,
        version: str,
        level: int,
        school: str,
        selection: dict[str, Any],
        principal_id: str,
        expected_revision: int,
        idempotency_key: str,
    ) -> dict[str, Any]:
        """Pay, wait, expire effects, and record one discovered spell atomically."""
        assert current.campaign_id is not None
        campaign_id = current.campaign_id
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if level < 1:
            raise ValueError("cantrips cannot be copied from a spellbook")
        campaign = campaigns.get(campaign_id)
        next_state = validate_party_state(deepcopy(campaign.state or {}))
        if authoritative_phase(campaign_id) != PROFILE_PLAY:
            raise CombatEngineError("spellbook copying is available only during play")
        source_owner = str(selection.get("source_owner") or "party").strip().casefold()
        if source_owner not in INVENTORY_OWNER_SCOPES:
            raise ValueError("spellbook copy source_owner must be party or character")
        source_item_id = str(selection.get("source_item_id") or "").strip()
        if not source_item_id:
            raise ValueError("spellbook copy requires source_item_id")
        source_inventory = (
            next_state["party"]["inventory"] if source_owner == "party" else sheet["inventory"]
        )
        source_item = next(
            (
                item
                for item in source_inventory.get("items", [])
                if str(item.get("id") or "") == source_item_id
            ),
            None,
        )
        if source_item is None:
            raise ValueError("spellbook copy source item is not in the selected inventory")
        mechanics = dict(source_item.get("mechanics") or {})
        if source_item.get("kind") != "spellbook":
            raise ValueError("spellbook copy source item must have kind=spellbook")
        campaign_edition = campaign_rules_edition(campaign.id)
        if str(mechanics.get("edition") or "") != campaign_edition:
            raise ValueError("spellbook copy source edition does not match the campaign")
        if not mechanics.get("copyable", False):
            raise ValueError("spellbook copy source is not marked copyable")
        if artifact_id not in set(mechanics.get("spell_ids") or []):
            raise ValueError("requested spell is not recorded in the source spellbook")

        feature_ids = {
            str(feature.get("id") or "") for feature in sheet.get("content", {}).get("features", [])
        }
        normalized_school = school.strip().casefold().split(" ", 1)[0]
        rule_facts = {
            "actor_id": current.id,
            "spell_id": artifact_id,
            "spell_level": level,
            "spell_school": normalized_school,
            "source_item_id": source_item_id,
            "source_was_previously_deciphered": bool(mechanics.get("deciphered", False)),
            **{f"has_feature:{feature_id}": True for feature_id in feature_ids if feature_id},
        }
        rule_context = effective_rule_context(campaign_id, facts=rule_facts)
        copy_rules = apply_rule_event(sheet, "spellbook.copy.before", rule_context)
        if copy_rules.status != "committed":
            return {
                "status": copy_rules.status,
                "pending": list(copy_rules.pending),
                "rule_receipts": list(copy_rules.receipts),
            }
        cost_percent = 100
        time_percent = 100
        for modifier in copy_rules.modifiers:
            if modifier.get("target") == "copy_cost_percent":
                cost_percent += int(modifier.get("value", 0) or 0)
            elif modifier.get("target") == "copy_time_percent":
                time_percent += int(modifier.get("value", 0) or 0)
        core_boundaries = ["dnd5e.core.spell.spellbook_copy"]
        if (
            normalized_school == "evocation"
            and "dnd5e.content.srd2014.feature.school-of-evocation-evocation-savant" in feature_ids
        ):
            cost_percent -= 50
            time_percent -= 50
            core_boundaries.append("dnd5e.core.spell.evocation_savant")
        if cost_percent <= 0 or time_percent <= 0:
            raise ValueError("spellbook copy modifiers must leave positive cost and time")
        base_cost_cp = level * 5000
        base_minutes = level * 120
        cost_cp = (base_cost_cp * cost_percent + 99) // 100
        minutes = (base_minutes * time_percent + 99) // 100
        hours = minutes / 60
        payment_owner = str(selection.get("payment_owner") or "character").strip().casefold()
        if payment_owner not in INVENTORY_OWNER_SCOPES:
            raise ValueError("spellbook copy payment_owner must be party or character")
        payment_wallet = (
            next_state["party"]["inventory"]["wallet"]
            if payment_owner == "party"
            else sheet["inventory"]["wallet"]
        )
        payment = spend_exact_wallet_payment(
            payment_wallet, selection.get("payment"), required_cp=cost_cp
        )

        next_state, time_transition = advance_state_game_time(
            next_state,
            period="minute",
            count=minutes,
        )
        next_world_time = time_transition["world_time_after"]
        elapsed_ticks = int(time_transition["elapsed_ticks"])

        world_duration = advance_world_effect_clocks(
            next_state,
            elapsed_ticks=elapsed_ticks,
            period_steps={"round": elapsed_ticks},
        )
        next_state = world_duration["state"]
        world_advanced = world_duration["advanced"]
        world_expired = world_duration["expired"]

        branch_id = require_current_branch(campaign_id, None)
        request_payload = {
            "operation": "character.spellbook.copy",
            "character_id": current.id,
            "artifact_id": artifact_id,
            "pack_id": pack_id,
            "version": version,
            "selection": selection,
        }
        scope = f"character-write:{campaign_id}:{branch_id}:{principal_id}:{current.id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay

        rule_context = context_with_facts(
            rule_context,
            copy_hours=hours,
            copy_minutes=minutes,
            copy_cost_cp=cost_cp,
            copy_cost_percent=cost_percent,
            copy_time_percent=time_percent,
        )
        receipts: list[dict[str, Any]] = list(copy_rules.receipts)
        updates: list[CharacterStateUpdate] = []
        advanced: dict[str, list[str]] = {}
        expired: dict[str, list[str]] = {}
        for character in characters.list(campaign_id=campaign_id):
            updated_sheet = sheet if character.id == current.id else character.sheet
            character_advanced: list[str] = []
            character_expired: list[str] = []
            duration = advance_elapsed_effect_durations(
                updated_sheet,
                elapsed_ticks=elapsed_ticks,
            )
            round_duration = advance_effect_durations(
                duration["sheet"],
                period="round",
                amount=int(time_transition["elapsed_ticks"]),
            )
            extension = apply_rule_event(
                round_duration["sheet"],
                "duration.advance",
                context_with_facts(
                    rule_context,
                    actor_id=character.id,
                    period="minute",
                    amount=minutes,
                ),
            )
            receipts.extend(extension.receipts)
            updated_sheet = extension.sheet
            character_advanced.extend(duration["advanced"])
            character_expired.extend(duration["expired"])
            character_advanced.extend(round_duration["advanced"])
            character_expired.extend(round_duration["expired"])
            if updated_sheet != character.sheet:
                updates.append(
                    CharacterStateUpdate(
                        character_id=character.id,
                        sheet=validate_character_sheet(updated_sheet),
                        notes=validate_character_notes(character.notes),
                        expected_revision=(
                            expected_revision if character.id == current.id else character.revision
                        ),
                    )
                )
            if character_advanced:
                advanced[character.id] = list(dict.fromkeys(character_advanced))
            if character_expired:
                expired[character.id] = list(dict.fromkeys(character_expired))
        receipts.extend(
            core_receipts(
                rule_context,
                core_boundaries,
                "character.spellbook.copy",
            )
        )
        current_update = next(item for item in updates if item.character_id == current.id)
        response = character_view(
            replace(
                current,
                sheet=current_update.sheet,
                notes=current_update.notes,
                revision=current.revision + 1,
            )
        )
        response["spellbook_copy"] = {
            "spell_id": artifact_id,
            "source_owner": source_owner,
            "source_item_id": source_item_id,
            "deciphered_during_copy": not bool(mechanics.get("deciphered", False)),
            "payment_owner": payment_owner,
            "payment": payment,
            "cost_cp": cost_cp,
            "base_cost_cp": base_cost_cp,
            "cost_percent": cost_percent,
            "minutes": minutes,
            "hours": hours,
            "base_minutes": base_minutes,
            "time_percent": time_percent,
            "game_time": time_transition["after"],
            "world_time": next_world_time,
            "advanced": advanced,
            "expired": expired,
            "world_advanced": list(dict.fromkeys(world_advanced)),
            "world_expired": list(dict.fromkeys(world_expired)),
            "rule_receipts": receipts,
        }
        StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=next_state,
            character_updates=updates,
            expected_campaign_revision=campaign.revision,
            operation="character.spellbook.copy",
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=response,
            ),
            rule_receipts=receipts,
        )
        return response

    @mcp.tool()
    def character_content_apply(
        character_id: str,
        artifact_id: str,
        selection: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Apply a catalog option when its structured card has a safe character target."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "content selection")
        if current.campaign_id is None:
            raise ValueError("content selection requires a campaign-bound character")
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for content selection"
            )
        candidates = available_content_artifacts(current.campaign_id)
        match = next((item for item in candidates if item[2].get("id") == artifact_id), None)
        if match is None:
            raise LookupError("content artifact is not available for this campaign")
        pack_id, version, artifact = match
        application_state = str(artifact.get("application_state") or "selection_ready")
        if application_state != "selection_ready":
            return {
                **_ruling_status(
                    "pending_ruling",
                    "missing_or_conflicting_source_review",
                ),
                "reason": (
                    "catalog artifact is source-linked but not selection-ready; "
                    "complete reviewer validation before applying it to an actor"
                ),
            }
        kind = str(artifact.get("kind") or "")
        card = deepcopy(dict(artifact.get("card") or {}))
        selection = deepcopy(selection or {})
        sheet = deepcopy(current.sheet)
        campaign = campaigns.get(current.campaign_id)
        phase = authoritative_phase(current.campaign_id)
        spellbook_copy: dict[str, Any] | None = None
        subclass_spell_grants: list[dict[str, Any]] = []
        feature_spell_grants: list[dict[str, Any]] = []
        replacing_feature_selection = False
        requested_method = str(selection.get("method") or "").strip().casefold()
        operation = (
            "character.spellbook.copy"
            if requested_method == "spellbook_copy"
            else "character.content.apply"
        )
        branch_id = require_current_branch(current.campaign_id, None)
        request_payload = {
            "operation": operation,
            "character_id": current.id,
            "artifact_id": artifact_id,
            "pack_id": pack_id,
            "version": version,
            "selection": selection,
        }
        replay = replay_idempotent(
            f"character-write:{current.campaign_id}:{branch_id}:{principal_id}:{current.id}",
            idempotency_key,
            request_payload,
        )
        if replay is not None:
            return replay
        provenance = {
            "id": artifact_id,
            "pack_id": pack_id,
            "pack_version": version,
            "rule_refs": list(artifact.get("rule_refs") or []),
            "mechanic_refs": list(artifact.get("mechanic_refs") or []),
        }

        def materialize_feature_spell(
            spell_match: tuple[str, str, dict[str, Any]],
            *,
            method: str,
            source_key: str,
            at_will: bool = False,
            allow_existing: bool = False,
        ) -> dict[str, Any]:
            spell_pack_id, spell_version, spell_artifact = spell_match
            spell_id = str(spell_artifact["id"])
            spell_card = next(
                (
                    item
                    for item in sheet["content"]["spells"]
                    if str(item.get("id") or "") == spell_id
                ),
                None,
            )
            if spell_card is not None and not allow_existing:
                raise ValueError("feature spell choice is already present")
            created = spell_card is None
            if spell_card is None:
                spell_card = deepcopy(dict(spell_artifact.get("card") or {}))
                spell_card.pop("classes", None)
                spell_card["grant"] = {
                    "source_type": "feature",
                    "source_key": source_key,
                    "method": method,
                }
                spell_card.update(
                    id=spell_id,
                    pack_id=spell_pack_id,
                    pack_version=spell_version,
                    rule_refs=list(spell_artifact.get("rule_refs") or []),
                    mechanic_refs=list(spell_artifact.get("mechanic_refs") or []),
                )
                sheet["content"]["spells"].append(spell_card)
            access = spell_card.setdefault("access", {})
            if method in {"known", "mystic_arcanum"}:
                access["known"] = True
            if created:
                access["prepared"] = False
            if at_will:
                at_will_source = f"{method}:{source_key}"
                access["at_will_sources"] = list(
                    dict.fromkeys(
                        [
                            *list(access.get("at_will_sources") or []),
                            at_will_source,
                        ]
                    )
                )
                access["at_will"] = True
            feature_spell_grants.append(
                {
                    "artifact_id": spell_id,
                    "name": str(spell_card.get("name") or spell_id),
                    "method": method,
                    "source_key": source_key,
                    "at_will": at_will,
                    "created": created,
                }
            )
            return spell_card

        if kind == "spell":
            if any(item.get("id") == artifact_id for item in sheet["content"]["spells"]):
                raise ValueError("content spell is already present")
            try:
                source_class = validate_spell_grant(
                    sheet,
                    card,
                    source_class=selection.get("source_class"),
                )
            except CombatEngineError as error:
                reason = str(error)
                if reason in {
                    "spell selection requires a recorded class",
                    "multiclass spell selection requires source_class",
                }:
                    return {"status": "pending_choice", "reason": reason}
                if reason == "spell artifact has no structured class-list eligibility":
                    return {
                        **_ruling_status(
                            "pending_ruling",
                            "missing_or_conflicting_source_review",
                        ),
                        "reason": reason,
                    }
                raise ValueError(reason) from error
            level = int(card.get("level", 0) or 0)
            preparation_mode = str(
                sheet.get("spellcasting", {}).get("preparation", {}).get("mode") or "known"
            )
            method = str(selection.get("method") or "").strip().casefold()
            if not method:
                method = (
                    "known"
                    if level == 0 or preparation_mode == "known"
                    else ("spellbook" if preparation_mode == "spellbook" else "class_prepared")
                )
            if method not in {"known", "spellbook", "spellbook_copy", "class_prepared"}:
                raise ValueError(
                    "spell selection method must be known, spellbook, spellbook_copy, "
                    "or class_prepared"
                )
            if method in {"spellbook", "spellbook_copy"} and preparation_mode != "spellbook":
                raise ValueError("only a spellbook caster can select a spellbook grant")
            if method == "class_prepared" and preparation_mode != "prepared":
                raise ValueError("class_prepared requires prepared-caster configuration")
            if method == "known" and level > 0 and preparation_mode != "known":
                raise ValueError(
                    "this caster records level 1+ spells as prepared or spellbook grants"
                )
            if method == "spellbook_copy":
                if source_class != "wizard":
                    raise ValueError("only wizard spells can be copied into this spellbook")
                if phase != PROFILE_PLAY:
                    raise CombatEngineError("spellbook copying is available only during play")
                spellbook_copy = {"level": level}
            elif phase != PROFILE_LOBBY:
                raise CombatEngineError(
                    "content grants belong to lobby setup or level advancement; "
                    "only source-bound spellbook_copy is legal during play"
                )
            card["grant"] = {
                "source_type": "class",
                "source_key": source_class,
                "method": method,
            }
            card.setdefault("access", {})["known"] = method == "known"
            card["access"]["prepared"] = False
            if method in {"spellbook", "spellbook_copy"}:
                spellbook = sheet["spellcasting"]["spellbook"]
                if not spellbook.get("enabled"):
                    raise ValueError("spellbook grant requires spellcasting.spellbook.enabled")
                spellbook["spell_ids"] = [
                    *list(spellbook.get("spell_ids") or []),
                    artifact_id,
                ]
            # Class eligibility belongs to the catalog artifact. The actor card
            # stores only the selected grant source and exact pack provenance.
            card.pop("classes", None)
            card.update(provenance)
            sheet["content"]["spells"].append(card)
        elif kind == "feat":
            if any(item.get("id") == artifact_id for item in sheet["content"]["feats"]):
                raise ValueError("content feat is already present")
            for prerequisite in card.get("prerequisites", []):
                if prerequisite.get("kind") != "ability_minimum":
                    ruling_kind = str(prerequisite.get("ruling_kind") or "source_or_scene_fact")
                    return {
                        **_ruling_status("pending_ruling", ruling_kind),
                        "reason": "feat has a prerequisite that needs Agent-as-DM review",
                    }
                ability = str(prerequisite.get("ability") or "")
                score = int(sheet.get("abilities", {}).get(ability, {}).get("score", 0) or 0)
                if score < int(prerequisite.get("minimum", 0) or 0):
                    raise ValueError(f"feat prerequisite is not met: {ability}")
            # Eligibility is validated against the catalog card, but the actor
            # feature schema stores the selected feat and exact pack provenance.
            card.pop("prerequisites", None)
            card.update(provenance)
            sheet["content"]["feats"].append(card)
        elif kind == "subclass":
            classes = list(sheet["progression"]["classes"])
            if not classes:
                return {
                    "status": "pending_choice",
                    "reason": "choose a base class before selecting a subclass",
                }
            declared_class = str(card.get("class_name") or "").strip()
            target_class = str(selection.get("target_class_name") or declared_class).strip()
            if not target_class:
                return {
                    "status": "pending_choice",
                    "reason": "subclass artifact needs class_name or target_class_name",
                }
            if declared_class and target_class.casefold() != declared_class.casefold():
                raise ValueError("subclass does not belong to target_class_name")
            target = next(
                (
                    item
                    for item in classes
                    if str(item.get("name") or "").casefold() == target_class.casefold()
                ),
                None,
            )
            if target is None:
                raise ValueError("subclass target class is not on this actor card")
            minimum_level = int(card.get("minimum_level", 1) or 1)
            if int(target.get("level", 0) or 0) < minimum_level:
                raise ValueError(
                    f"{target_class} must reach level {minimum_level} for this subclass"
                )
            existing_subclass = str(target.get("subclass") or "")
            if existing_subclass and existing_subclass != str(card.get("name") or artifact_id):
                raise ValueError("target class already has a different subclass")
            target["subclass"] = str(card.get("name") or artifact_id)
            sheet["progression"]["classes"] = classes
            domain_spell_ids: list[str] = []
            for spell_grant in card.get("always_prepared_spells", []):
                if int(spell_grant.get("minimum_level", 1) or 1) > int(target.get("level", 0) or 0):
                    continue
                spell_name = str(spell_grant.get("name") or "").strip()
                spell_match = next(
                    (
                        item
                        for item in candidates
                        if item[2].get("kind") == "spell"
                        and str(dict(item[2].get("card") or {}).get("name") or "").casefold()
                        == spell_name.casefold()
                    ),
                    None,
                )
                if spell_match is None:
                    return {
                        **_ruling_status(
                            "pending_ruling",
                            "missing_or_conflicting_source_review",
                        ),
                        "reason": (
                            f"subclass spell is not available in the active catalog: {spell_name}"
                        ),
                    }
                spell_pack_id, spell_version, spell_artifact = spell_match
                spell_id = str(spell_artifact["id"])
                domain_spell_ids.append(spell_id)
                spell_card = next(
                    (item for item in sheet["content"]["spells"] if item.get("id") == spell_id),
                    None,
                )
                if spell_card is None:
                    spell_card = deepcopy(dict(spell_artifact.get("card") or {}))
                    spell_card.pop("classes", None)
                    sheet["content"]["spells"].append(spell_card)
                spell_card["grant"] = {
                    "source_type": "subclass",
                    "source_key": str(card.get("name") or artifact_id),
                    "method": "class_prepared",
                }
                spell_card.setdefault("access", {})["known"] = False
                spell_card["access"]["prepared"] = True
                spell_card["access"]["always_prepared"] = True
                spell_card.update(
                    id=spell_id,
                    pack_id=spell_pack_id,
                    pack_version=spell_version,
                    rule_refs=list(spell_artifact.get("rule_refs") or []),
                    mechanic_refs=list(spell_artifact.get("mechanic_refs") or []),
                )
            if domain_spell_ids:
                preparation = sheet["spellcasting"]["preparation"]
                preparation["selected_spell_ids"] = [
                    item
                    for item in preparation.get("selected_spell_ids", [])
                    if item not in set(domain_spell_ids)
                ]
        elif kind == "background":
            existing_background = str(sheet["progression"].get("background") or "")
            base_background = str(card.get("name") or artifact_id)
            custom_name = str(selection.get("custom_name") or "").strip()
            custom_skills_raw = selection.get("skills")
            if bool(custom_name) != (custom_skills_raw is not None):
                return {
                    "status": "pending_choice",
                    "reason": (
                        "custom background requires both custom_name and exactly two skill choices"
                    ),
                }
            selected_background = custom_name or base_background
            if existing_background and existing_background != selected_background:
                raise ValueError("character already has a different background")
            grants = dict(card.get("background_grants") or {})
            requirements = dict(grants.get("choices") or {})
            language_count = int(requirements.get("language_count", 0) or 0)
            selected_languages = [str(item).strip() for item in selection.get("languages", [])]
            if len(selected_languages) != language_count or any(
                not item for item in selected_languages
            ):
                return {
                    "status": "pending_choice",
                    "reason": f"background requires exactly {language_count} language choices",
                }
            if len({item.casefold() for item in selected_languages}) != len(selected_languages):
                raise ValueError("background language choices must be distinct")
            if custom_skills_raw is None:
                selected_skills = [
                    str(item).casefold() for item in card.get("skill_proficiencies", [])
                ]
            else:
                if not isinstance(custom_skills_raw, list):
                    raise ValueError("custom background skills must be an array")
                selected_skills = [str(item).strip().casefold() for item in custom_skills_raw]
                if len(selected_skills) != 2 or any(not item for item in selected_skills):
                    return {
                        "status": "pending_choice",
                        "reason": "custom background requires exactly two skill choices",
                    }
                if len(set(selected_skills)) != 2:
                    raise ValueError("custom background skill choices must be distinct")
                unknown_skills = [
                    skill for skill in selected_skills if skill not in sheet["skills"]
                ]
                if unknown_skills:
                    raise ValueError(
                        "custom background references unknown skills: " + ", ".join(unknown_skills)
                    )
                duplicate_skills = [
                    skill
                    for skill in selected_skills
                    if sheet["skills"][skill]["proficiency"] != "none"
                ]
                if duplicate_skills:
                    return {
                        "status": "pending_choice",
                        "reason": (
                            "custom background skill choices must replace proficiencies "
                            "already granted by another source: " + ", ".join(duplicate_skills)
                        ),
                    }
            equipment_item_ids_raw = selection.get("equipment_item_ids", [])
            if not isinstance(equipment_item_ids_raw, list):
                raise ValueError("background equipment_item_ids must be an array")
            equipment_item_ids = [str(item).strip() for item in equipment_item_ids_raw]
            if any(not item for item in equipment_item_ids):
                raise ValueError("background equipment item ids must not be empty")
            if len(equipment_item_ids) != len(set(equipment_item_ids)):
                raise ValueError("background equipment item ids must be distinct")
            inventory_item_ids = {str(item["id"]) for item in sheet["inventory"]["items"]}
            missing_equipment = [
                item_id for item_id in equipment_item_ids if item_id not in inventory_item_ids
            ]
            if missing_equipment:
                raise ValueError(
                    "background equipment references unknown inventory items: "
                    + ", ".join(missing_equipment)
                )
            sheet["progression"]["background"] = selected_background
            grants["languages"] = selected_languages
            grants["equipment_item_ids"] = equipment_item_ids
            grants["choices"] = {
                **requirements,
                "base_background": base_background,
                "customized": bool(custom_name),
                "selected_skills": selected_skills,
            }
            sheet["progression"]["background_grants"] = {
                **sheet["progression"]["background_grants"],
                **grants,
            }
            sheet["traits"]["languages"] = list(
                dict.fromkeys([*sheet["traits"]["languages"], *selected_languages])
            )
            for skill_key in selected_skills:
                if skill_key not in sheet["skills"]:
                    raise ValueError(f"background references an unknown skill: {skill_key}")
                sheet["skills"][skill_key]["proficiency"] = "proficient"
        elif kind == "species":
            selected_species = str(card.get("name") or artifact_id)
            constitution_score_before = int(sheet["abilities"]["constitution"]["score"])
            base_species = str(card.get("base_species") or selected_species)
            existing_species = str(sheet["progression"].get("species") or "")
            if existing_species and existing_species.casefold() not in {
                selected_species.casefold(),
                base_species.casefold(),
            }:
                raise ValueError("character already has a different species")
            if any(
                item.get("artifact_id") == artifact_id for item in sheet["content"]["selections"]
            ):
                raise ValueError("content species is already present")
            grants = dict(card.get("grants") or {})
            if grants.get("unresolved"):
                return {
                    **_ruling_status(
                        "pending_ruling",
                        "missing_or_conflicting_source_review",
                    ),
                    "reason": "species has unresolved structured grants",
                    "missing": list(grants.get("unresolved") or []),
                }
            selected_languages = _validated_distinct_choices(
                selection.get("languages"),
                count=int(grants.get("language_choice_count", 0) or 0),
                label="species languages",
            )
            selected_skills = [
                item.casefold()
                for item in _validated_distinct_choices(
                    selection.get("skills"),
                    count=int(grants.get("skill_choice_count", 0) or 0),
                    label="species skills",
                )
            ]
            for skill in selected_skills:
                if skill not in sheet["skills"]:
                    raise ValueError(f"species references an unknown skill: {skill}")
            tool_options = {
                str(item).casefold(): str(item) for item in grants.get("tool_choices", [])
            }
            selected_tools = _validated_distinct_choices(
                selection.get("tools"),
                count=1 if tool_options else 0,
                label="species tools",
            )
            if any(item.casefold() not in tool_options for item in selected_tools):
                raise ValueError("species tool choice is not one of the allowed options")
            selected_tools = [tool_options[item.casefold()] for item in selected_tools]
            ability_choice = dict(grants.get("ability_choice") or {})
            selected_abilities = [
                item.casefold()
                for item in _validated_distinct_choices(
                    selection.get("abilities"),
                    count=int(ability_choice.get("count", 0) or 0),
                    label="species abilities",
                )
            ]
            excluded_abilities = {
                str(item).casefold() for item in ability_choice.get("exclude", [])
            }
            if any(item not in sheet["abilities"] for item in selected_abilities):
                raise ValueError("species ability choice is not a valid ability")
            if excluded_abilities.intersection(selected_abilities):
                raise ValueError("species ability choice cannot repeat a fixed increase")
            values_include_grants = bool(selection.get("values_include_species_grants", False))
            abilities_include_grants = bool(
                selection.get("ability_scores_include_species_grants", values_include_grants)
            )
            hp_includes_grants = bool(
                selection.get("hit_points_include_species_grants", values_include_grants)
            )
            if not abilities_include_grants:
                increases = dict(grants.get("ability_score_increases") or {})
                for ability in selected_abilities:
                    increases[ability] = int(increases.get(ability, 0)) + int(
                        ability_choice.get("amount", 0) or 0
                    )
                for ability, amount in increases.items():
                    sheet["abilities"][ability]["score"] = int(
                        sheet["abilities"][ability]["score"]
                    ) + int(amount)
                sheet = apply_constitution_score_hit_point_change(
                    sheet,
                    previous_score=constitution_score_before,
                    new_score=int(sheet["abilities"]["constitution"]["score"]),
                    source=f"{selected_species}: Constitution ability score increase",
                    adjust_current=True,
                )
            if not hp_includes_grants:
                hp_per_level = int(grants.get("hp_per_level", 0) or 0)
                if hp_per_level:
                    features = [
                        item for item in grants.get("features", []) if isinstance(item, dict)
                    ]
                    hp_feature = next(
                        (
                            item
                            for item in features
                            if "hit point" in str(item.get("description") or "").casefold()
                            or "tough" in str(item.get("name") or "").casefold()
                        ),
                        None,
                    )
                    feature_name = str((hp_feature or {}).get("name") or "").strip()
                    hp_source = (
                        f"{selected_species}: {feature_name}"
                        if feature_name
                        else f"{selected_species}: per-level hit-point grant"
                    )
                    sheet = apply_per_level_hit_point_bonus(
                        sheet,
                        amount=hp_per_level,
                        source=hp_source,
                        adjust_current=True,
                    )
            if grants.get("size"):
                sheet["traits"]["size"] = str(grants["size"])
            if int(grants.get("walk_speed", 0) or 0):
                sheet["combat"]["speed"]["walk"] = int(grants["walk_speed"])
            if int(grants.get("darkvision_ft", 0) or 0):
                sheet["traits"]["senses"]["darkvision"] = int(grants["darkvision_ft"])
            sheet["traits"]["languages"] = list(
                dict.fromkeys(
                    [
                        *sheet["traits"]["languages"],
                        *list(grants.get("languages") or []),
                        *selected_languages,
                    ]
                )
            )
            fixed_skills = [str(item).casefold() for item in grants.get("skill_proficiencies", [])]
            for skill in [*fixed_skills, *selected_skills]:
                if skill not in sheet["skills"]:
                    raise ValueError(f"species references an unknown skill: {skill}")
                sheet["skills"][skill]["proficiency"] = "proficient"
            proficiencies = sheet["traits"]["proficiencies"]
            proficiencies["weapons"] = list(
                dict.fromkeys(
                    [*proficiencies["weapons"], *list(grants.get("weapon_proficiencies") or [])]
                )
            )
            proficiencies["tools"] = list(
                dict.fromkeys(
                    [
                        *proficiencies["tools"],
                        *list(grants.get("tool_proficiencies") or []),
                        *selected_tools,
                    ]
                )
            )
            sheet["traits"]["resistances"] = list(
                dict.fromkeys(
                    [*sheet["traits"]["resistances"], *list(grants.get("resistances") or [])]
                )
            )
            cantrip_id = str(selection.get("cantrip_artifact_id") or "")
            cantrip_requirement = dict(grants.get("cantrip_choice") or {})
            if cantrip_requirement:
                cantrip_match = next(
                    (item for item in candidates if item[2].get("id") == cantrip_id), None
                )
                if cantrip_match is None:
                    raise ValueError("species cantrip_artifact_id is not available")
                cantrip_pack_id, cantrip_version, cantrip_artifact = cantrip_match
                cantrip_card = deepcopy(dict(cantrip_artifact.get("card") or {}))
                if (
                    cantrip_artifact.get("kind") != "spell"
                    or int(cantrip_card.get("level", -1)) != int(cantrip_requirement["level"])
                    or str(cantrip_requirement["class"]).casefold()
                    not in {str(item).casefold() for item in cantrip_card.get("classes", [])}
                ):
                    raise ValueError(
                        "species cantrip choice does not meet its class and level rule"
                    )
                if any(item.get("id") == cantrip_id for item in sheet["content"]["spells"]):
                    raise ValueError("species cantrip is already present")
                cantrip_card.pop("classes", None)
                cantrip_card["grant"] = {
                    "source_type": "species",
                    "source_key": selected_species,
                    "method": "known",
                }
                cantrip_card.setdefault("access", {})["known"] = True
                cantrip_card["access"]["prepared"] = False
                cantrip_card.update(
                    id=cantrip_id,
                    pack_id=cantrip_pack_id,
                    pack_version=cantrip_version,
                    rule_refs=list(cantrip_artifact.get("rule_refs") or []),
                    mechanic_refs=list(cantrip_artifact.get("mechanic_refs") or []),
                )
                sheet["content"]["spells"].append(cantrip_card)
            elif cantrip_id:
                raise ValueError("species does not grant a cantrip choice")
            feature_choices = {
                "languages": selected_languages,
                "skills": selected_skills,
                "tools": selected_tools,
                "abilities": selected_abilities,
                "cantrip_artifact_id": cantrip_id,
            }
            for feature in grants.get("features", []):
                feature_card = deepcopy(dict(feature))
                feature_card.update(
                    pack_id=pack_id,
                    pack_version=version,
                    rule_refs=list(artifact.get("rule_refs") or []),
                    mechanic_refs=list(artifact.get("mechanic_refs") or []),
                )
                if any(feature_choices.values()):
                    feature_card["choices"] = feature_choices
                sheet["content"]["features"].append(feature_card)
            sheet["progression"]["species"] = selected_species
        elif kind in {"feature", "activity"}:
            section = "features" if kind == "feature" else "activities"
            existing_content = next(
                (item for item in sheet["content"][section] if item.get("id") == artifact_id),
                None,
            )
            grant_level = int(selection.get("grant_level", 0) or 0)
            repeatable_levels = {
                int(value)
                for value in card.get("repeatable_selection_levels", [])
                if int(value) > 0
            }
            if kind == "feature" and not grant_level and repeatable_levels:
                grant_level = int(card.get("minimum_level", 1) or 1)
            initial_requirements = dict(
                dict(card.get("selection_requirements_by_level") or {}).get(str(grant_level))
                or card.get("selection_requirements")
                or {}
            )
            replacement_study_minutes = int(
                initial_requirements.get("replacement_study_minutes", 0) or 0
            )
            replacing_feature_selection = bool(
                existing_content is not None
                and kind == "feature"
                and replacement_study_minutes
                and selection.get("replace_existing") is True
            )
            if existing_content is not None and (
                not replacing_feature_selection
                and (kind != "feature" or grant_level not in repeatable_levels)
            ):
                raise ValueError(f"content {kind} is already present")
            if grant_level and grant_level not in repeatable_levels:
                raise ValueError("feature grant_level is not a repeatable selection level")
            if existing_content is not None and any(
                int(item.get("level", 0) or 0) == grant_level
                for item in existing_content.get("advancement_grants", [])
            ):
                raise ValueError("feature selection is already recorded for this level")
            if kind == "feature":
                declared_class = str(card.get("class_name") or "").strip()
                declared_subclass = str(card.get("subclass_name") or "").strip()
                minimum_level = int(card.get("minimum_level", 1) or 1)
                target = next(
                    (
                        item
                        for item in sheet["progression"]["classes"]
                        if str(item.get("name") or "").casefold() == declared_class.casefold()
                    ),
                    None,
                )
                if declared_class and target is None:
                    raise ValueError("feature class is not on this actor card")
                if target is not None and int(target.get("level", 0) or 0) < minimum_level:
                    raise ValueError(
                        f"{declared_class} must reach level {minimum_level} for this feature"
                    )
                if target is not None and grant_level > int(target.get("level", 0) or 0):
                    raise ValueError("feature grant_level exceeds the actor's class level")
                if declared_subclass and (
                    target is None
                    or str(target.get("subclass") or "").casefold() != declared_subclass.casefold()
                ):
                    raise ValueError("feature subclass is not selected on this actor card")
                requirements = initial_requirements
                selection_kind = str(requirements.get("kind") or "")
                unsupported_requirement_fields = (
                    set(requirements) - SUPPORTED_FEATURE_SELECTION_REQUIREMENT_FIELDS
                )
                if unsupported_requirement_fields:
                    raise RulesetUnavailableError(
                        "feature selection requirements are not executable: "
                        f"{sorted(unsupported_requirement_fields)}"
                    )
                unsupported_prerequisite_fields = {
                    field
                    for prerequisite in dict(
                        requirements.get("option_prerequisites") or {}
                    ).values()
                    for field in dict(prerequisite)
                    if field not in SUPPORTED_FEATURE_OPTION_PREREQUISITE_FIELDS
                }
                if unsupported_prerequisite_fields:
                    raise RulesetUnavailableError(
                        "feature option prerequisites are not executable: "
                        f"{sorted(unsupported_prerequisite_fields)}"
                    )
                if selection_kind not in SUPPORTED_FEATURE_SELECTION_KINDS:
                    raise RulesetUnavailableError(
                        f"feature selection kind is not executable: {selection_kind}"
                    )
                choice_field = str(requirements.get("field") or "")
                allowed_selection_fields = {"grant_level"}
                if choice_field:
                    allowed_selection_fields.add(choice_field)
                if int(dict(card.get("mechanical_grants") or {}).get("hp_per_class_level", 0) or 0):
                    allowed_selection_fields.add("initial_setup_full_hp")
                if replacing_feature_selection:
                    allowed_selection_fields.update(
                        {
                            "replace_existing",
                            "study_started_elapsed_ticks",
                            "study_started_elapsed_minutes",
                        }
                    )
                unsupported_selection_fields = set(selection) - allowed_selection_fields
                if unsupported_selection_fields:
                    raise ValueError(
                        "feature selection has unsupported fields: "
                        f"{sorted(unsupported_selection_fields)}"
                    )
                if replacing_feature_selection:
                    if phase != PROFILE_PLAY:
                        raise CombatEngineError(
                            "feature selection replacement is available only during play"
                        )
                    study_started_ticks = selection.get("study_started_elapsed_ticks")
                    legacy_study_minutes = selection.get("study_started_elapsed_minutes")
                    if legacy_study_minutes is not None and (
                        isinstance(legacy_study_minutes, bool)
                        or not isinstance(legacy_study_minutes, int)
                    ):
                        raise CombatEngineError(
                            "feature replacement study start must be an integer"
                        )
                    if study_started_ticks is None and legacy_study_minutes is not None:
                        study_started_ticks = legacy_study_minutes * TICKS_PER_MINUTE
                    if isinstance(study_started_ticks, bool) or not isinstance(
                        study_started_ticks, int
                    ):
                        raise CombatEngineError(
                            "feature replacement requires study_started_elapsed_ticks"
                        )
                    if (
                        legacy_study_minutes is not None
                        and study_started_ticks != legacy_study_minutes * TICKS_PER_MINUTE
                    ):
                        raise CombatEngineError(
                            "legacy study_started_elapsed_minutes must match "
                            "study_started_elapsed_ticks"
                        )
                    current_elapsed = dict(dict(campaign.state or {}).get("game_time") or {}).get(
                        "elapsed_ticks"
                    )
                    if isinstance(current_elapsed, bool) or not isinstance(current_elapsed, int):
                        raise CombatEngineError(
                            "feature replacement requires the campaign game timeline"
                        )
                    if (
                        study_started_ticks < 0
                        or current_elapsed - study_started_ticks
                        < replacement_study_minutes * TICKS_PER_MINUTE
                    ):
                        raise CombatEngineError(
                            "feature replacement has not completed its required "
                            f"{replacement_study_minutes} minutes of study"
                        )
                if choice_field:
                    if requirements.get("kind") == "ability_score_increase":
                        selected_increases = selection.get(choice_field)
                        if not isinstance(selected_increases, dict) or not selected_increases:
                            raise ValueError(
                                "feature ability_score_increases must be a non-empty object"
                            )
                        normalized_increases: dict[str, int] = {}
                        for ability, amount in selected_increases.items():
                            normalized_ability = str(ability).strip().casefold()
                            if normalized_ability not in sheet["abilities"]:
                                raise ValueError(
                                    "feature ability score increase names an unknown ability"
                                )
                            if (
                                isinstance(amount, bool)
                                or not isinstance(amount, int)
                                or amount <= 0
                            ):
                                raise ValueError(
                                    "feature ability score increases must be positive integers"
                                )
                            normalized_increases[normalized_ability] = amount
                        distribution = sorted(normalized_increases.values(), reverse=True)
                        allowed = [
                            sorted(
                                [int(amount) for amount in distribution_option],
                                reverse=True,
                            )
                            for distribution_option in requirements.get("allowed_distributions", [])
                        ]
                        if distribution not in allowed:
                            raise ValueError(
                                "feature ability score increases do not match an allowed "
                                "distribution"
                            )
                        maximum_score = int(requirements.get("maximum_score", 20) or 20)
                        previous_constitution = int(sheet["abilities"]["constitution"]["score"])
                        for ability, amount in normalized_increases.items():
                            old_score = int(sheet["abilities"][ability]["score"])
                            if old_score + amount > maximum_score:
                                raise ValueError(
                                    "feature ability score increase exceeds its maximum"
                                )
                            sheet["abilities"][ability]["score"] = old_score + amount
                        sheet = apply_constitution_score_hit_point_change(
                            sheet,
                            previous_score=previous_constitution,
                            new_score=int(sheet["abilities"]["constitution"]["score"]),
                            source=(
                                f"{declared_class} level {grant_level}: Ability Score Improvement"
                            ),
                        )
                    elif requirements.get("kind") == "favored_enemy":
                        favored_enemy = selection.get(choice_field)
                        if not isinstance(favored_enemy, dict):
                            raise ValueError("feature favored_enemy must be a structured object")
                        unexpected_enemy_fields = set(favored_enemy) - {
                            "creature_type",
                            "humanoid_races",
                            "enemy_speaks_language",
                            "language",
                        }
                        if unexpected_enemy_fields:
                            raise ValueError(
                                "feature favored_enemy has unsupported fields: "
                                f"{sorted(unexpected_enemy_fields)}"
                            )
                        creature_type = str(favored_enemy.get("creature_type") or "").strip()
                        humanoid_races = _validated_distinct_choices(
                            favored_enemy.get("humanoid_races"),
                            count=(
                                int(requirements.get("humanoid_race_count", 2) or 2)
                                if creature_type.casefold() == "humanoid"
                                else 0
                            ),
                            label="favored enemy humanoid races",
                        )
                        creature_options = {
                            str(item).casefold()
                            for item in requirements.get("creature_type_options", [])
                        }
                        if creature_type.casefold() == "humanoid":
                            if not humanoid_races:
                                raise ValueError("humanoid favored enemy requires two races")
                        elif creature_type.casefold() not in creature_options:
                            raise ValueError("favored enemy creature_type is not an allowed option")
                        language = str(favored_enemy.get("language") or "").strip()
                        speaks_language = favored_enemy.get("enemy_speaks_language")
                        if requirements.get("language_if_spoken") and not isinstance(
                            speaks_language, bool
                        ):
                            raise ValueError(
                                "favored enemy must explicitly record whether it speaks a language"
                            )
                        if speaks_language and not language:
                            raise ValueError("favored enemy requires its associated language")
                        if not speaks_language and language:
                            raise ValueError(
                                "favored enemy language must be empty when the enemy speaks none"
                            )
                        if language:
                            known_languages = {
                                str(item).casefold() for item in sheet["traits"]["languages"]
                            }
                            if language.casefold() in known_languages:
                                raise ValueError("favored enemy language is already known")
                            sheet["traits"]["languages"].append(language)
                        normalized_enemy = (
                            "humanoid:"
                            + ",".join(sorted(item.casefold() for item in humanoid_races))
                            if creature_type.casefold() == "humanoid"
                            else creature_type.casefold()
                        )
                        prior_enemies: set[str] = set()
                        if existing_content is not None:
                            prior_choices = [
                                dict(existing_content.get("choices") or {}),
                                *[
                                    dict(item.get("choices") or {})
                                    for item in existing_content.get("advancement_grants", [])
                                ],
                            ]
                            for prior in prior_choices:
                                value = prior.get(choice_field)
                                if not isinstance(value, dict):
                                    continue
                                prior_type = str(value.get("creature_type") or "").casefold()
                                if prior_type == "humanoid":
                                    prior_races = [
                                        str(item).casefold()
                                        for item in value.get("humanoid_races", [])
                                    ]
                                    prior_enemies.add("humanoid:" + ",".join(sorted(prior_races)))
                                elif prior_type:
                                    prior_enemies.add(prior_type)
                        if normalized_enemy in prior_enemies:
                            raise ValueError("favored enemy choice was already selected")
                    elif requirements.get("kind") in {
                        "known_spell_grants",
                        "mystic_arcanum",
                        "spell_mastery",
                        "signature_spells",
                    }:
                        spell_ids = _validated_distinct_choices(
                            selection.get(choice_field),
                            count=int(requirements.get("count", 1) or 1),
                            label=f"feature {choice_field}",
                        )
                        spell_matches = []
                        for spell_id in spell_ids:
                            spell_match = next(
                                (
                                    item
                                    for item in candidates
                                    if str(item[2].get("id") or "") == spell_id
                                    and item[2].get("kind") == "spell"
                                ),
                                None,
                            )
                            if spell_match is None:
                                raise ValueError("feature spell artifact is unavailable")
                            spell_matches.append(spell_match)
                        spell_levels = [
                            int(dict(item[2].get("card") or {}).get("level", 0) or 0)
                            for item in spell_matches
                        ]
                        eligible_class = str(requirements.get("eligible_class") or "").casefold()
                        if eligible_class and eligible_class != "any":
                            for spell_match in spell_matches:
                                eligible_classes = {
                                    str(item).casefold()
                                    for item in dict(spell_match[2].get("card") or {}).get(
                                        "classes", []
                                    )
                                }
                                if eligible_class not in eligible_classes:
                                    raise ValueError(
                                        "feature spell is not on the required class list"
                                    )
                        feature_kind = str(requirements.get("kind") or "")
                        if feature_kind == "known_spell_grants":
                            maximum_spell_level = max(
                                [
                                    int(level)
                                    for level, resource in dict(
                                        sheet["spellcasting"].get("spell_slots") or {}
                                    ).items()
                                    if int(dict(resource).get("max", 0) or 0) > 0
                                ]
                                + [
                                    int(
                                        dict(sheet["spellcasting"].get("pact_magic") or {}).get(
                                            "slot_level", 0
                                        )
                                        or 0
                                    )
                                ]
                            )
                            if any(level > maximum_spell_level for level in spell_levels):
                                raise ValueError(
                                    "feature spell exceeds the actor's available spell level"
                                )
                            source_class = str(
                                requirements.get("source_class") or declared_class
                            ).title()
                            for spell_match in spell_matches:
                                materialize_feature_spell(
                                    spell_match,
                                    method="known",
                                    source_key=source_class,
                                )
                        elif feature_kind == "mystic_arcanum":
                            required_level = int(requirements.get("spell_level", 0) or 0)
                            if spell_levels != [required_level]:
                                raise ValueError("Mystic Arcanum requires the exact spell level")
                            spell_card = materialize_feature_spell(
                                spell_matches[0],
                                method="mystic_arcanum",
                                source_key="Warlock",
                            )
                            resource_key = f"mystic_arcanum:{spell_matches[0][2]['id']}"
                            sheet["resources"][resource_key] = {
                                "label": (
                                    f"Mystic Arcanum: {spell_card.get('name') or spell_ids[0]}"
                                ),
                                "value": 1,
                                "max": 1,
                                "recovers_on": "long_rest",
                                "source_key": "Warlock",
                            }
                        elif feature_kind == "spell_mastery":
                            required_levels = sorted(
                                int(value)
                                for value in requirements.get("required_spell_levels", [])
                            )
                            if sorted(spell_levels) != required_levels:
                                raise ValueError(
                                    "Spell Mastery requires one 1st-level and one 2nd-level spell"
                                )
                            spellbook_ids = set(
                                sheet["spellcasting"]["spellbook"].get("spell_ids", [])
                            )
                            if not set(spell_ids).issubset(spellbook_ids):
                                raise ValueError("Spell Mastery choices must be in the spellbook")
                            if replacing_feature_selection:
                                previous_spell_ids = [
                                    str(item)
                                    for item in dict(existing_content.get("choices") or {}).get(
                                        choice_field, []
                                    )
                                ]
                                if set(previous_spell_ids) == set(spell_ids):
                                    raise ValueError(
                                        "Spell Mastery replacement must exchange "
                                        "at least one selected spell"
                                    )
                                mastery_source = "spell_mastery:Wizard"
                                for previous_spell_id in set(previous_spell_ids) - set(spell_ids):
                                    previous_spell = next(
                                        (
                                            item
                                            for item in sheet["content"]["spells"]
                                            if str(item.get("id") or "") == previous_spell_id
                                        ),
                                        None,
                                    )
                                    if previous_spell is None:
                                        raise ValueError(
                                            "recorded Spell Mastery choice is "
                                            "missing from the actor card"
                                        )
                                    previous_access = previous_spell.setdefault("access", {})
                                    sources = [
                                        str(item)
                                        for item in previous_access.get("at_will_sources", [])
                                        if str(item) != mastery_source
                                    ]
                                    previous_access["at_will_sources"] = sources
                                    if sources:
                                        previous_access["at_will"] = True
                                    elif (
                                        str(
                                            dict(previous_spell.get("grant") or {}).get("method")
                                            or ""
                                        )
                                        != "eldritch_invocation"
                                    ):
                                        previous_access["at_will"] = False
                            for spell_match in spell_matches:
                                materialize_feature_spell(
                                    spell_match,
                                    method="spell_mastery",
                                    source_key="Wizard",
                                    at_will=True,
                                    allow_existing=True,
                                )
                        else:
                            required_levels = sorted(
                                int(value)
                                for value in requirements.get("required_spell_levels", [])
                            )
                            if sorted(spell_levels) != required_levels:
                                raise ValueError("Signature Spells requires two 3rd-level spells")
                            spellbook_ids = set(
                                sheet["spellcasting"]["spellbook"].get("spell_ids", [])
                            )
                            if not set(spell_ids).issubset(spellbook_ids):
                                raise ValueError("Signature Spell choices must be in the spellbook")
                            for spell_match in spell_matches:
                                spell_card = materialize_feature_spell(
                                    spell_match,
                                    method="signature_spells",
                                    source_key="Wizard",
                                    allow_existing=True,
                                )
                                access = spell_card.setdefault("access", {})
                                access["always_prepared"] = True
                                access["prepared"] = True
                                spell_id = str(spell_match[2]["id"])
                                sheet["resources"][f"signature_spell:{spell_id}"] = {
                                    "label": (
                                        f"Signature Spell: {spell_card.get('name') or spell_id}"
                                    ),
                                    "value": 1,
                                    "max": 1,
                                    "unlimited": False,
                                    "recovers_on": "short_rest",
                                    "source_key": "Wizard",
                                }
                    elif requirements.get("kind") == "bonus_cantrip":
                        spell_artifact_id = str(selection.get(choice_field) or "").strip()
                        spell_match = next(
                            (
                                item
                                for item in candidates
                                if str(item[2].get("id") or "") == spell_artifact_id
                            ),
                            None,
                        )
                        if spell_match is None:
                            raise ValueError("bonus cantrip spell_artifact_id is unavailable")
                        spell_pack_id, spell_version, spell_artifact = spell_match
                        spell_card = deepcopy(dict(spell_artifact.get("card") or {}))
                        eligible_class = str(
                            requirements.get("eligible_class") or declared_class
                        ).casefold()
                        if (
                            spell_artifact.get("kind") != "spell"
                            or int(spell_card.get("level", -1))
                            != int(requirements.get("spell_level", 0) or 0)
                            or eligible_class
                            not in {str(item).casefold() for item in spell_card.get("classes", [])}
                        ):
                            raise ValueError("bonus cantrip does not meet its class and level rule")
                        if any(
                            item.get("id") == spell_artifact_id
                            for item in sheet["content"]["spells"]
                        ):
                            raise ValueError("bonus cantrip is already present")
                        spell_card.pop("classes", None)
                        spell_card["grant"] = {
                            "source_type": "subclass",
                            "source_key": declared_subclass or declared_class,
                            "method": "known",
                        }
                        spell_card.setdefault("access", {})["known"] = True
                        spell_card["access"]["prepared"] = False
                        spell_card.update(
                            id=spell_artifact_id,
                            pack_id=spell_pack_id,
                            pack_version=spell_version,
                            rule_refs=list(spell_artifact.get("rule_refs") or []),
                            mechanic_refs=list(spell_artifact.get("mechanic_refs") or []),
                        )
                        sheet["content"]["spells"].append(spell_card)
                    else:
                        selected = selection.get(choice_field)
                        if int(requirements.get("count", 1) or 1) == 1 and not isinstance(
                            selected, list
                        ):
                            selected_values = [str(selected or "").strip()]
                        else:
                            selected_values = _validated_distinct_choices(
                                selected,
                                count=int(requirements.get("count", 1) or 1),
                                label=f"feature {choice_field}",
                            )
                        if any(not item for item in selected_values):
                            raise ValueError(f"feature {choice_field} choice is required")
                        options = {str(item).casefold() for item in requirements.get("options", [])}
                        if options and any(
                            item.casefold() not in options for item in selected_values
                        ):
                            raise ValueError("feature choice is not one of the allowed options")
                        if requirements.get("requires_new_choice"):
                            uniqueness_scope = str(
                                requirements.get("choice_uniqueness_scope") or artifact_id
                            )
                            prior_values: set[str] = set()
                            for prior_feature in sheet["content"]["features"]:
                                prior_choice_sets = [
                                    dict(prior_feature.get("choices") or {}),
                                    *[
                                        dict(item.get("choices") or {})
                                        for item in prior_feature.get("advancement_grants", [])
                                    ],
                                ]
                                for prior_choices in prior_choice_sets:
                                    recorded_scope = str(
                                        prior_choices.get("_choice_uniqueness_scope") or ""
                                    )
                                    if recorded_scope:
                                        same_scope = recorded_scope == uniqueness_scope
                                    elif uniqueness_scope == "fighting_style":
                                        same_scope = str(
                                            prior_feature.get("name") or ""
                                        ).casefold() in {
                                            "fighting style",
                                            "additional fighting style",
                                        }
                                    else:
                                        same_scope = (
                                            str(prior_feature.get("id") or "") == artifact_id
                                        )
                                    if not same_scope:
                                        continue
                                    prior_value = prior_choices.get(choice_field)
                                    if isinstance(prior_value, list):
                                        prior_values.update(
                                            str(item).casefold() for item in prior_value
                                        )
                                    elif prior_value is not None:
                                        prior_values.add(str(prior_value).casefold())
                            if any(item.casefold() in prior_values for item in selected_values):
                                raise ValueError("feature choice was already selected")
                        option_prerequisites = dict(requirements.get("option_prerequisites") or {})
                        at_will_spells = dict(requirements.get("at_will_spells") or {})
                        for selected_value in selected_values:
                            prerequisite = dict(option_prerequisites.get(selected_value) or {})
                            if target is not None and int(target.get("level", 0) or 0) < int(
                                prerequisite.get("minimum_level", 0) or 0
                            ):
                                raise ValueError(
                                    "eldritch invocation level prerequisite is not met"
                                )
                            required_pact = str(prerequisite.get("required_pact_boon") or "")
                            if required_pact and not any(
                                required_pact.casefold()
                                == str(
                                    dict(feature.get("choices") or {}).get("option") or ""
                                ).casefold()
                                for feature in sheet["content"]["features"]
                            ):
                                raise ValueError("eldritch invocation pact prerequisite is not met")
                            required_cantrip = str(prerequisite.get("required_cantrip") or "")
                            if required_cantrip and not any(
                                int(spell.get("level", -1)) == 0
                                and str(spell.get("name") or "").casefold()
                                == required_cantrip.casefold()
                                and bool(dict(spell.get("access") or {}).get("known"))
                                for spell in sheet["content"]["spells"]
                            ):
                                raise ValueError(
                                    "eldritch invocation cantrip prerequisite is not met"
                                )
                            at_will_spell = str(at_will_spells.get(selected_value) or "")
                            if at_will_spell:
                                at_will_match = next(
                                    (
                                        item
                                        for item in candidates
                                        if item[2].get("kind") == "spell"
                                        and str(
                                            dict(item[2].get("card") or {}).get("name") or ""
                                        ).casefold()
                                        == at_will_spell.casefold()
                                    ),
                                    None,
                                )
                                if at_will_match is None:
                                    raise RulesetUnavailableError(
                                        "eldritch invocation at-will spell is "
                                        f"unavailable: {at_will_spell}"
                                    )
                                materialize_feature_spell(
                                    at_will_match,
                                    method="eldritch_invocation",
                                    source_key=selected_value,
                                    at_will=True,
                                    allow_existing=True,
                                )
                        if requirements.get("requires_existing_proficiency"):
                            for item in selected_values:
                                skill = sheet["skills"].get(item.casefold())
                                if requirements.get("skills_only") and skill is None:
                                    raise ValueError(
                                        "feature expertise choice must be an existing skill"
                                    )
                                tool_key = item.casefold()
                                tool_known = tool_key in {
                                    value.casefold()
                                    for value in sheet["traits"]["proficiencies"]["tools"]
                                }
                                tool_expertise = {
                                    value.casefold()
                                    for value in sheet["traits"]["proficiencies"]["tool_expertise"]
                                }
                                if not tool_known and (
                                    skill is None or skill.get("proficiency") == "none"
                                ):
                                    raise ValueError(
                                        "feature expertise choice requires an existing proficiency"
                                    )
                                if requirements.get("requires_new_expertise") and (
                                    (skill is not None and skill.get("proficiency") == "expertise")
                                    or (tool_known and tool_key in tool_expertise)
                                ):
                                    raise ValueError(
                                        "feature expertise choice already has expertise"
                                    )
                                if skill is not None:
                                    skill["proficiency"] = "expertise"
                                elif tool_known:
                                    sheet["traits"]["proficiencies"]["tool_expertise"].append(item)
                        if requirements.get("grants_skill_proficiency"):
                            for item in selected_values:
                                skill = sheet["skills"].get(item.casefold())
                                if skill is None:
                                    raise ValueError(
                                        "feature proficiency choice must be an existing skill"
                                    )
                                if (
                                    requirements.get("requires_untrained_skill")
                                    and skill.get("proficiency") != "none"
                                ):
                                    raise ValueError(
                                        "feature proficiency choice must be an untrained skill"
                                    )
                                skill["proficiency"] = "proficient"
                mechanical_grants = dict(card.get("mechanical_grants") or {})
                unsupported_grants = set(mechanical_grants) - SUPPORTED_FEATURE_MECHANICAL_GRANTS
                if unsupported_grants:
                    raise RulesetUnavailableError(
                        "feature mechanical grants are not executable: "
                        f"{sorted(unsupported_grants)}"
                    )
                hp_per_class_level = int(mechanical_grants.get("hp_per_class_level", 0) or 0)
                if hp_per_class_level:
                    initial_setup_full_hp = selection.get("initial_setup_full_hp", False)
                    if not isinstance(initial_setup_full_hp, bool):
                        raise ValueError("initial_setup_full_hp must be a boolean")
                    if initial_setup_full_hp:
                        hp_before_grant = dict(sheet.get("combat", {}).get("hp") or {})
                        if phase != PROFILE_LOBBY:
                            raise CombatEngineError(
                                "initial_setup_full_hp is available only in lobby setup"
                            )
                        if int(hp_before_grant.get("value", 0) or 0) != int(
                            hp_before_grant.get("max", 0) or 0
                        ):
                            raise CombatEngineError(
                                "initial_setup_full_hp requires a character at "
                                "its pre-grant hit point maximum"
                            )
                    source_class = str(card.get("class_name") or "").strip()
                    source_level = next(
                        (
                            int(item.get("level", 0) or 0)
                            for item in sheet["progression"]["classes"]
                            if str(item.get("name") or "").casefold() == source_class.casefold()
                        ),
                        0,
                    )
                    if not source_class or source_level < 1:
                        raise ValueError(
                            "feature per-class-level hit points require its recorded class"
                        )
                    sheet = apply_per_level_hit_point_bonus(
                        sheet,
                        amount=hp_per_class_level,
                        source=f"{card.get('name')}: {source_class} class levels",
                        adjust_current=initial_setup_full_hp,
                    )
                unarmored_base = int(mechanical_grants.get("unarmored_base", 0) or 0)
                if unarmored_base:
                    sheet, _ = add_effect(
                        sheet,
                        {
                            "name": str(card.get("name") or "Unarmored AC"),
                            "kind": "feature",
                            "source": artifact_id,
                            "duration": {"period": "manual", "remaining": 0},
                            "changes": [
                                {
                                    "path": "combat.ac.unarmored_base",
                                    "mode": "override",
                                    "value": unarmored_base,
                                }
                            ],
                            "description": (
                                "Class feature alternate AC calculation while not wearing armor."
                            ),
                        },
                    )
                unarmored_formula = dict(mechanical_grants.get("unarmored_formula") or {})
                if unarmored_formula:
                    if any(
                        change.get("path") == "combat.ac.unarmored_formula"
                        for effect in sheet.get("effects", [])
                        if bool(effect.get("active", True))
                        for change in effect.get("changes", [])
                    ):
                        raise ValueError(
                            "a multiclass character that already has Unarmored "
                            "Defense cannot gain it again"
                        )
                    sheet, _ = add_effect(
                        sheet,
                        {
                            "name": str(card.get("name") or "Unarmored Defense"),
                            "kind": "feature",
                            "source": artifact_id,
                            "duration": {"period": "manual", "remaining": 0},
                            "changes": [
                                {
                                    "path": "combat.ac.unarmored_formula",
                                    "mode": "override",
                                    "value": unarmored_formula,
                                }
                            ],
                            "description": (
                                "Class feature alternate AC calculation while "
                                "its armor and shield conditions are met."
                            ),
                        },
                    )
                armor = sheet["traits"]["proficiencies"]["armor"]
                for proficiency in mechanical_grants.get("armor_proficiencies") or []:
                    if str(proficiency).casefold() not in {str(item).casefold() for item in armor}:
                        armor.append(proficiency)
                languages = sheet["traits"]["languages"]
                for language in mechanical_grants.get("languages") or []:
                    if str(language).casefold() not in {str(item).casefold() for item in languages}:
                        languages.append(language)
                for resource_key, resource in dict(
                    mechanical_grants.get("resources") or {}
                ).items():
                    normalized_key = str(resource_key).strip()
                    if not normalized_key:
                        raise ValueError("feature resource grant has an empty key")
                    existing = sheet["resources"].get(normalized_key)
                    if (
                        existing is not None
                        and existing != resource
                        and normalized_key != "channel_divinity"
                    ):
                        raise ValueError(
                            f"feature resource grant conflicts with existing resource: "
                            f"{normalized_key}"
                        )
                    if existing is None:
                        sheet["resources"][normalized_key] = deepcopy(dict(resource))
                resource_key = str(card.get("resource_key") or "")
                if resource_key and resource_key not in sheet["resources"]:
                    raise ValueError(
                        f"feature requires an unapplied shared resource: {resource_key}"
                    )
                for metadata_key in (
                    "class_name",
                    "subclass_name",
                    "minimum_level",
                    "unlock_levels",
                    "repeatable_selection_levels",
                    "selection_requirements",
                    "selection_requirements_by_level",
                    "mechanical_grants",
                    "choice_metadata",
                    "always_prepared_spell_options",
                ):
                    card.pop(metadata_key, None)
                recorded_selection = {
                    key: value
                    for key, value in selection.items()
                    if key
                    not in {
                        "grant_level",
                        "replace_existing",
                        "study_started_elapsed_ticks",
                        "study_started_elapsed_minutes",
                    }
                }
                grant_record = {
                    "level": grant_level,
                    "choices": deepcopy(recorded_selection),
                    "pack_id": pack_id,
                    "pack_version": version,
                    "rule_refs": list(artifact.get("rule_refs") or []),
                }
                if replacing_feature_selection:
                    current_record = next(
                        item for item in sheet["content"][section] if item.get("id") == artifact_id
                    )
                    previous_choices = dict(current_record.get("choices") or {})
                    replacement_history = list(previous_choices.get("_replacement_history") or [])
                    current_elapsed = int(
                        dict(dict(campaign.state or {}).get("game_time") or {})["elapsed_ticks"]
                    )
                    study_started_ticks = selection.get("study_started_elapsed_ticks")
                    if study_started_ticks is None:
                        study_started_ticks = (
                            int(selection["study_started_elapsed_minutes"]) * TICKS_PER_MINUTE
                        )
                    replacement_history.append(
                        {
                            "previous_spell_artifact_ids": list(
                                previous_choices.get(choice_field) or []
                            ),
                            "study_started_elapsed_ticks": int(study_started_ticks),
                            "study_completed_elapsed_ticks": current_elapsed,
                            "study_minutes": (current_elapsed - int(study_started_ticks))
                            // TICKS_PER_MINUTE,
                        }
                    )
                    current_record["choices"] = {
                        **recorded_selection,
                        "_replacement_history": replacement_history,
                    }
                elif existing_content is not None:
                    current_record = next(
                        item for item in sheet["content"][section] if item.get("id") == artifact_id
                    )
                    current_record.setdefault("advancement_grants", []).append(grant_record)
                else:
                    if recorded_selection:
                        card["choices"] = {
                            **dict(card.get("choices") or {}),
                            **recorded_selection,
                        }
                    if grant_level:
                        card["advancement_grants"] = [grant_record]
                    card.update(provenance)
                    sheet["content"][section].append(card)
                if artifact.get("kind") == "feature" and dict(artifact.get("card") or {}).get(
                    "always_prepared_spell_options"
                ):
                    subclass_spell_grants = refresh_level_unlocked_subclass_spells(
                        current.campaign_id,
                        sheet,
                        class_name=declared_class,
                        branch_id=branch_id,
                    )
            else:
                card.update(provenance)
                sheet["content"][section].append(card)
        else:
            return {
                **_ruling_status("pending_ruling", "agent_dm_adjudication"),
                "reason": (f"{kind} is catalogued but needs an Agent-as-DM reviewed application"),
            }
        if kind in {"subclass", "background", "species"}:
            if any(
                item.get("artifact_id") == artifact_id for item in sheet["content"]["selections"]
            ):
                raise ValueError("content selection is already present")
            sheet["content"]["selections"].append(
                {
                    "artifact_id": artifact_id,
                    "kind": kind,
                    "name": str(card.get("name") or artifact_id),
                    "pack_id": pack_id,
                    "pack_version": version,
                    "rule_refs": list(artifact.get("rule_refs") or []),
                    "mechanic_refs": list(artifact.get("mechanic_refs") or []),
                    "selection": selection,
                }
            )
        resource_sync = synchronize_class_feature_resources(sheet)
        sheet = resource_sync["sheet"]
        if spellbook_copy is not None:
            return settle_spellbook_copy(
                current=current,
                sheet=sheet,
                artifact_id=artifact_id,
                pack_id=pack_id,
                version=version,
                level=int(spellbook_copy["level"]),
                school=str(card.get("definition", {}).get("school") or card.get("school") or ""),
                selection=selection,
                principal_id=principal_id,
                expected_revision=expected_revision,
                idempotency_key=idempotency_key,
            )
        if phase != PROFILE_LOBBY and not replacing_feature_selection:
            raise CombatEngineError("content grants belong to lobby setup or level advancement")
        return update_sheet(
            character_id,
            sheet,
            operation="character.content.apply",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={
                "artifact_id": artifact_id,
                "pack_id": pack_id,
                "version": version,
                "selection": selection,
            },
            response_extra=(
                {
                    **(
                        {"subclass_spell_grants": subclass_spell_grants}
                        if subclass_spell_grants
                        else {}
                    ),
                    **(
                        {"feature_spell_grants": feature_spell_grants}
                        if feature_spell_grants
                        else {}
                    ),
                }
                or None
            ),
        )

    @mcp.tool()
    def character_rule_artifact_add(
        character_id: str,
        pack_id: str,
        version: str,
        artifact_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Add one activated pack card to an actor without copying executable rule logic."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "rule artifact changes")
        if current.campaign_id is None:
            raise ValueError("rule artifacts require a campaign-bound character")
        active = next(
            (
                item
                for item in rule_packs.activations(current.campaign_id)
                if item.pack_id == pack_id and item.enabled
            ),
            None,
        )
        if active is None or active.version != version:
            raise ValueError("the exact rule-pack version must be enabled on this branch")
        pack = rule_packs.get_version(pack_id, version)
        artifact = next((item for item in pack.artifacts if item.get("id") == artifact_id), None)
        if artifact is None:
            raise LookupError(artifact_id)
        section = {
            "feature": "features",
            "activity": "activities",
        }.get(str(artifact.get("kind") or ""))
        if section is None:
            raise ValueError(
                "spell, feat, subclass, and background artifacts must use "
                "character_content_apply for rule-aware validation"
            )
        sheet = deepcopy(current.sheet)
        if any(item.get("id") == artifact_id for item in sheet["content"][section]):
            raise ValueError("rule artifact is already present on this character")
        card = deepcopy(artifact.get("card") or {})
        card["id"] = artifact_id
        card["pack_id"] = pack_id
        card["pack_version"] = version
        card["rule_refs"] = list(artifact.get("rule_refs") or [])
        card["mechanic_refs"] = list(artifact.get("mechanic_refs") or [])
        sheet["content"][section].append(card)
        return update_sheet(
            character_id,
            sheet,
            operation="character.rule_artifact.add",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={
                "pack_id": pack_id,
                "version": version,
                "artifact_id": artifact_id,
            },
        )

    @mcp.tool()
    def skill_list() -> list[dict[str, str]]:
        """List installed D&D DM, campaign-manager, and module-generator skill documents."""
        return [
            {
                "id": item.id,
                "title": item.title,
                "source": item.source,
                "checksum": item.checksum,
            }
            for item in catalog.list()
        ]

    @mcp.tool()
    def skill_read(skill_id: str) -> str:
        """Read one source-of-truth SKILL.md document."""
        return catalog.read(skill_id)

    @mcp.tool()
    def skill_asset_list(source: str | None = None) -> list[dict[str, str]]:
        """List bundled text references, templates, and data files."""
        return [
            {
                "id": asset.id,
                "source": asset.source,
                "checksum": asset.checksum,
                "resource_uri": (f"sagasmith://asset/{catalog.resource_id(asset.id)}"),
            }
            for asset in catalog.assets()
            if source is None or asset.source == source
        ]

    @mcp.tool()
    def skill_asset_read(asset_id: str) -> str:
        """Read one text skill asset by the id returned from skill_asset_list."""
        return catalog.read_asset(asset_id)

    @mcp.resource("sagasmith://skill/{skill_id}")
    def skill_resource(skill_id: str) -> str:
        """Skill document resource addressed by its id from skill_list."""
        return catalog.read(skill_id)

    @mcp.resource(
        "sagasmith://skills/overview",
        name="SagaSmith D&D skill overview",
        description="Installed D&D and module-generation skill document ids.",
        mime_type="text/markdown",
    )
    def skill_overview_resource() -> str:
        """Expose a static skill resource for MCP clients without template discovery."""
        lines = ["# SagaSmith D&D Skills", ""]
        for document in catalog.list():
            lines.append(
                f"- `{document.id}` ({document.source}, sha256:{document.checksum}): "
                f"{document.title}"
            )
        lines.extend(
            [
                "",
                "Read a document with `skill_read` or `sagasmith://skill/{skill_id}`.",
                (
                    "Use `skill_asset_list` and `skill_asset_read` for references, data, "
                    "and templates."
                ),
            ]
        )
        return "\n".join(lines)

    @mcp.resource("sagasmith://asset/{resource_id}")
    def skill_asset_resource(resource_id: str) -> str:
        """Skill reference, template, or data resource addressed by its encoded resource id."""
        return catalog.read_resource_asset(resource_id)

    @mcp.prompt()
    def dnd_dm(campaign_id: str, objective: str) -> str:
        """Start a D&D DM turn with the bundled D&D DM instructions available as a resource."""
        return (
            f"You are running campaign {campaign_id}. Objective: {objective}\n\n"
            "Read sagasmith://skill/dnd.full.skills.dnd-dm before acting. Use module_search and "
            "rule_search for factual retrieval; record durable changes through the MCP tools."
        )

    @mcp.prompt()
    def module_generator(campaign_id: str, brief: str) -> str:
        """Generate an importable adventure module using the bundled module-generation workflow."""
        return (
            f"Create a D&D module for campaign {campaign_id}. Brief: {brief}\n\n"
            "Read sagasmith://skill/modulegen.root first. Write the resulting Markdown with "
            "module_import(action='stage'), then inspect, validate, ingest, and activate the "
            "returned import job."
        )

    # The public MCP contract intentionally exposes domain facades rather than
    # one tool per storage operation.  These facades call the mature, narrowly
    # validated operations above; they must not reimplement writes or weaken
    # revision, idempotency, access, or combat guards.
    character_content_apply_legacy = character_content_apply
    character_spell_prepare_legacy = character_spell_prepare
    campaign_clock_set_legacy = campaign_clock_set
    campaign_advance_effects_legacy = campaign_advance_effects
    character_check_legacy = character_check
    # These facade names intentionally replace same-named legacy tools.
    for replaced_tool_name in (
        "character_content_apply",
        "character_spell_prepare",
        "campaign_clock_set",
        "campaign_advance_effects",
        "character_check",
    ):
        mcp.remove_tool(replaced_tool_name)

    def facade_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
        if payload is None:
            return {}
        if not isinstance(payload, dict):
            raise ValueError("payload must be an object")
        return dict(payload)

    def required(payload: dict[str, Any], name: str) -> Any:
        value = payload.get(name)
        if value is None or value == "":
            raise ValueError(f"payload.{name} is required")
        return value

    def strict_facade_payload(
        payload: dict[str, Any] | None,
        *,
        action: str,
        allowed: set[str],
        required_names: tuple[str, ...] = (),
    ) -> dict[str, Any]:
        """Validate one facade action without accepting an untyped payload escape hatch."""
        data = facade_payload(payload)
        unknown = sorted(set(data) - allowed)
        if unknown:
            raise ValueError(f"unsupported {action} payload fields: {', '.join(unknown)}")
        for name in required_names:
            required(data, name)
        return data

    def require_facade_phase(campaign_id: str, action: str, *phases: str) -> None:
        phase = authoritative_phase(campaign_id)
        if phase not in phases:
            allowed = ", ".join(phases)
            raise ExposureError(
                f"{action} is only available during {allowed}; current phase is {phase}."
            )

    def optional_datetime(value: Any, name: str) -> datetime | None:
        if value is None or value == "":
            return None
        if isinstance(value, datetime):
            return value
        try:
            return datetime.fromisoformat(str(value))
        except ValueError as exc:
            raise ValueError(f"payload.{name} must be ISO-8601") from exc

    def facade_result(action: str, result: Any) -> dict[str, Any]:
        return _facade_result(action, result)

    def facade_render_result(rendered: Any) -> CallToolResult:
        """Preserve native image content while satisfying a facade's structured output."""
        if (
            not isinstance(rendered, list)
            or len(rendered) != 2
            or not isinstance(rendered[0], dict)
            or not isinstance(rendered[1], Image)
        ):
            raise TypeError("render facade received an invalid image result")
        metadata = dict(rendered[0])
        return CallToolResult(
            content=[
                TextContent(
                    type="text",
                    text=json.dumps(
                        metadata,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ),
                ),
                rendered[1].to_image_content(),
            ],
            structuredContent=metadata,
        )

    @mcp.tool()
    def character_check(
        campaign_id: str,
        action: Literal["check", "group", "contest"] = "check",
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Resolve an individual, group, or contested check in the Play phase."""
        require_facade_phase(campaign_id, f"character_check({action})", PROFILE_PLAY)
        if action == "group":
            data = strict_facade_payload(
                payload,
                action="character_check(group)",
                allowed={
                    "actor_ids",
                    "ability",
                    "dc",
                    "proficient",
                    "bonus",
                    "advantage",
                    "disadvantage",
                    "rule_facts",
                },
                required_names=("actor_ids", "ability", "dc"),
            )
            return character_group_check(
                campaign_id,
                data["actor_ids"],
                data["ability"],
                data["dc"],
                data.get("proficient", False),
                data.get("bonus", 0),
                data.get("advantage", False),
                data.get("disadvantage", False),
                data.get("rule_facts"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        if action == "contest":
            data = strict_facade_payload(
                payload,
                action="character_check(contest)",
                allowed={
                    "source_actor_id",
                    "target_actor_id",
                    "source_ability",
                    "target_ability",
                    "source_proficient",
                    "target_proficient",
                    "source_bonus",
                    "target_bonus",
                    "source_advantage",
                    "source_disadvantage",
                    "target_advantage",
                    "target_disadvantage",
                    "source_rule_facts",
                    "target_rule_facts",
                },
                required_names=(
                    "source_actor_id",
                    "target_actor_id",
                    "source_ability",
                    "target_ability",
                ),
            )
            result = character_contest(
                campaign_id,
                data["source_actor_id"],
                data["target_actor_id"],
                data["source_ability"],
                data["target_ability"],
                data.get("source_proficient", False),
                data.get("target_proficient", False),
                data.get("source_bonus", 0),
                data.get("target_bonus", 0),
                data.get("source_advantage", False),
                data.get("source_disadvantage", False),
                data.get("target_advantage", False),
                data.get("target_disadvantage", False),
                data.get("source_rule_facts"),
                data.get("target_rule_facts"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
            return result
        data = strict_facade_payload(
            payload,
            action="character_check(check)",
            allowed={
                "actor_id",
                "kind",
                "ability",
                "dc",
                "proficient",
                "bonus",
                "advantage",
                "disadvantage",
                "rule_facts",
            },
            required_names=("actor_id", "kind", "ability"),
        )
        if data["kind"] not in ACTOR_CHECK_KINDS:
            raise ValueError(
                "character_check(check).payload.kind must be ability, check, "
                "save, or death_save"
            )
        result = character_check_legacy(
            campaign_id,
            data["actor_id"],
            data["kind"],
            data["ability"],
            data.get("dc", 0),
            data.get("proficient", False),
            data.get("bonus", 0),
            data.get("advantage", False),
            data.get("disadvantage", False),
            data.get("rule_facts"),
            principal_id,
            expected_revision,
            branch_id,
            idempotency_key,
        )
        return result

    @mcp.tool()
    def chase(
        campaign_id: str,
        action: Literal["start", "query", "take_turn", "end"],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Run the source-reviewed 2014 chase procedure only during Play."""
        require_facade_phase(campaign_id, f"chase({action})", PROFILE_PLAY)
        if action == "query":
            data = strict_facade_payload(
                payload,
                action="chase(query)",
                allowed=set(),
            )
            assert not data
            return facade_result(action, chase_query(campaign_id, principal_id))
        if action == "start":
            data = strict_facade_payload(
                payload,
                action="chase(start)",
                allowed={
                    "participant_ids",
                    "quarry_ids",
                    "initial_distance_ft",
                    "scene_id",
                    "source_ref",
                    "source_excerpt",
                    "name",
                    "participant_config",
                    "close_transition",
                },
                required_names=(
                    "participant_ids",
                    "quarry_ids",
                    "initial_distance_ft",
                    "scene_id",
                    "source_ref",
                    "source_excerpt",
                ),
            )
            result = chase_start(
                campaign_id,
                data["participant_ids"],
                data["quarry_ids"],
                data["initial_distance_ft"],
                data["scene_id"],
                data["source_ref"],
                data["source_excerpt"],
                data.get("name", "Chase"),
                data.get("participant_config"),
                data.get("close_transition"),
                principal_id,
                branch_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "take_turn":
            data = strict_facade_payload(
                payload,
                action="chase(take_turn)",
                allowed={
                    "actor_id",
                    "turn_action",
                    "complication_choice",
                    "stand_from_prone",
                    "quarry_visibility",
                    "expected_actor_revision",
                },
                required_names=(
                    "actor_id",
                    "turn_action",
                    "stand_from_prone",
                    "quarry_visibility",
                    "expected_actor_revision",
                ),
            )
            if "complication_choice" not in data:
                raise ValueError("payload.complication_choice is required")
            turn_action = data.get("turn_action", "dash")
            if turn_action not in {"dash", "move", "drop_out"}:
                raise ValueError("payload.turn_action must be dash, move, or drop_out")
            result = chase_take_turn(
                campaign_id,
                data["actor_id"],
                turn_action,
                data.get("complication_choice", ""),
                data.get("stand_from_prone", True),
                data.get("quarry_visibility"),
                principal_id,
                branch_id,
                expected_revision,
                data.get("expected_actor_revision"),
                idempotency_key,
            )
        else:
            data = strict_facade_payload(
                payload,
                action="chase(end)",
                allowed={
                    "status",
                    "summary",
                    "source_ref",
                    "source_excerpt",
                },
                required_names=(
                    "status",
                    "summary",
                    "source_ref",
                    "source_excerpt",
                ),
            )
            status = data["status"]
            if status not in CHASE_MANUAL_OUTCOME_STATUSES:
                raise ValueError(
                    "payload.status must be caught, destination_reached, "
                    "quarry_escaped, or pursuers_abandoned"
                )
            result = chase_end(
                campaign_id,
                status,
                data["summary"],
                data["source_ref"],
                data["source_excerpt"],
                principal_id,
                branch_id,
                expected_revision,
                idempotency_key,
            )
        return facade_result(action, result)

    @mcp.tool()
    def import_query(
        campaign_id: str,
        view: Literal["get", "list"] = "list",
        job_id: str | None = None,
        kind: Literal["rulebook", "module"] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read staged rulebook or module import jobs without changing their state."""
        if view == "get":
            return facade_result(
                view,
                import_job_get(campaign_id, required({"job_id": job_id}, "job_id"), principal_id),
            )
        return facade_result(view, import_job_list(campaign_id, kind, principal_id))

    @mcp.tool()
    def rule_import(
        campaign_id: Annotated[str, Field(title="Campaign")],
        action: Literal[
            "discover",
            "stage",
            "inspect",
            "render_page",
            "recover_statblock",
            "ingest",
            "review_statblock",
            "extract_candidates",
            "review",
            "compile",
            "install",
            "activate",
        ],
        payload: dict[str, Any] | None = None,
        principal_id: Annotated[str, Field(title="Principal")] = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: Annotated[int | None, Field(title="Revision")] = None,
        branch_id: Annotated[str | None, Field(title="BranchID")] = None,
        idempotency_key: Annotated[str | None, Field(title="Request Key")] = None,
    ) -> dict[str, Any]:
        """Run reviewed rule imports; direct rule ingestion stays internal."""
        if action == "discover":
            data = strict_facade_payload(
                payload,
                action="rule_import(discover)",
                allowed=set(),
            )
            assert not data
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            discovered = storage.discover_rulebooks()
            return facade_result(
                action,
                {"count": len(discovered), "documents": discovered},
            )
        if action == "stage":
            data = strict_facade_payload(
                payload,
                action="rule_import(stage)",
                allowed={
                    "source_path",
                    "source_key",
                    "title",
                    "edition",
                    "locale",
                    "publication_id",
                    "version",
                    "authority",
                },
                required_names=("source_path", "source_key", "title", "edition"),
            )
            staged = rule_document_stage(campaign_id, required(data, "source_path"), principal_id)
            artifact = staged["artifact"]
            result = rule_import_job_create(
                campaign_id,
                artifact,
                required(data, "source_key"),
                required(data, "title"),
                required(data, "edition"),
                data.get("locale", "en"),
                data.get("publication_id", ""),
                data.get("version", ""),
                data.get("authority", "supplement"),
                principal_id,
                idempotency_key,
            )
            return facade_result(action, {**staged, **result})
        if action == "render_page":
            require_facade_phase(
                campaign_id,
                "rule_import(render_page)",
                PROFILE_LOBBY,
            )
            data = strict_facade_payload(
                payload,
                action="rule_import(render_page)",
                allowed={"job_id", "page_number", "scale"},
                required_names=("job_id", "page_number"),
            )
            return facade_render_result(  # type: ignore[return-value]
                rule_document_page_render(
                    campaign_id,
                    data["job_id"],
                    data["page_number"],
                    data.get("scale", 1.5),
                    principal_id,
                )
            )
        if action == "recover_statblock":
            require_facade_phase(
                campaign_id,
                "rule_import(recover_statblock)",
                PROFILE_LOBBY,
            )
            data = strict_facade_payload(
                payload,
                action="rule_import(recover_statblock)",
                allowed={"job_id", "name", "page_number", "agent_fill"},
                required_names=("job_id", "name"),
            )
            return facade_result(
                action,
                rule_statblock_ocr_recover(
                    campaign_id,
                    data["job_id"],
                    data["name"],
                    data.get("page_number"),
                    principal_id,
                    idempotency_key,
                    data.get("agent_fill"),
                ),
            )
        if action == "inspect":
            data = strict_facade_payload(
                payload,
                action="rule_import(inspect)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                rule_import_job_inspect(campaign_id, data["job_id"], principal_id, idempotency_key),
            )
        if action == "ingest":
            data = strict_facade_payload(
                payload,
                action="rule_import(ingest)",
                allowed={"job_id", "acknowledge_warnings"},
                required_names=("job_id",),
            )
            acknowledge_warnings = data.get("acknowledge_warnings", False)
            if not isinstance(acknowledge_warnings, bool):
                raise ValueError("payload.acknowledge_warnings must be a boolean")
            return facade_result(
                action,
                rule_import_job_ingest(
                    campaign_id,
                    data["job_id"],
                    acknowledge_warnings,
                    principal_id,
                    idempotency_key,
                ),
            )
        if action == "review_statblock":
            review_data = facade_payload(payload)
            if "base_review_id" in review_data:
                data = strict_facade_payload(
                    payload,
                    action="rule_import(review_statblock)",
                    allowed={
                        "job_id",
                        "base_review_id",
                        "observation",
                        "agent_fill",
                    },
                    required_names=(
                        "job_id",
                        "base_review_id",
                        "observation",
                        "agent_fill",
                    ),
                )
                return facade_result(
                    action,
                    rule_statblock_review_from_base(
                        campaign_id,
                        str(data["job_id"]),
                        str(data["base_review_id"]),
                        data["observation"],
                        data["agent_fill"],
                        principal_id,
                        idempotency_key,
                    ),
                )
            data = strict_facade_payload(
                payload,
                action="rule_import(review_statblock)",
                allowed={
                    "job_id",
                    "page_number",
                    "normalized_content",
                    "observation",
                    "review_mode",
                    "evidence_chunk_ids",
                    "evidence_exclusions",
                    "agent_fill",
                },
                required_names=(
                    "job_id",
                    "page_number",
                    "normalized_content",
                    "observation",
                ),
            )
            return facade_result(
                action,
                rule_statblock_review(
                    campaign_id,
                    str(data["job_id"]),
                    data["page_number"],
                    data["normalized_content"],
                    data["observation"],
                    principal_id,
                    idempotency_key,
                    data.get("review_mode", "visual"),
                    data.get("evidence_chunk_ids"),
                    data.get("agent_fill"),
                    None,
                    data.get("evidence_exclusions"),
                ),
            )
        if action == "extract_candidates":
            data = strict_facade_payload(
                payload,
                action="rule_import(extract_candidates)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                rule_content_candidates_extract(
                    campaign_id, data["job_id"], principal_id, idempotency_key
                ),
            )
        if action == "review":
            data = strict_facade_payload(
                payload,
                action="rule_import(review)",
                allowed={"job_id", "decisions"},
                required_names=("job_id", "decisions"),
            )
            return facade_result(
                action,
                import_job_review_candidates(
                    campaign_id,
                    data["job_id"],
                    data["decisions"],
                    principal_id,
                    idempotency_key,
                ),
            )
        if action == "compile":
            data = strict_facade_payload(
                payload,
                action="rule_import(compile)",
                allowed={"job_id", "manifest", "mechanics", "provenance"},
                required_names=("job_id", "manifest"),
            )
            return facade_result(
                action,
                rule_import_job_compile(
                    campaign_id,
                    data["job_id"],
                    data["manifest"],
                    data.get("mechanics"),
                    data.get("provenance"),
                    principal_id,
                    idempotency_key,
                ),
            )
        if action == "install":
            data = strict_facade_payload(
                payload,
                action="rule_import(install)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                rule_import_job_install(campaign_id, data["job_id"], principal_id, idempotency_key),
            )
        data = strict_facade_payload(
            payload,
            action="rule_import(activate)",
            allowed={"job_id"},
            required_names=("job_id",),
        )
        return facade_result(
            action,
            rule_import_job_activate(
                campaign_id,
                data["job_id"],
                principal_id,
                branch_id,
                expected_revision,
                idempotency_key,
            ),
        )

    @mcp.tool()
    def module_import(
        campaign_id: str,
        action: Literal[
            "stage",
            "inspect",
            "validate",
            "ingest",
            "activate",
            "attach_asset",
        ],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Run the staged module-import state machine and activate only reviewed revisions."""
        if action == "stage":
            data = strict_facade_payload(
                payload,
                action="module_import(stage)",
                allowed={"source_path", "name", "content", "title", "source_key"},
            )
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            source_path = data.get("source_path")
            generated_fields = {"name", "content"}.intersection(data)
            if source_path is not None and generated_fields:
                raise ValueError("stage accepts either source_path or name+content, not both")
            if source_path is not None:
                staged = storage.stage_module(str(source_path))
                artifact = str(staged["artifact"])
            else:
                staged = module_write(
                    required(data, "name"), required(data, "content"), principal_id
                )
                artifact = staged["artifact"]
            result = module_import_job_create(
                campaign_id,
                artifact,
                data.get("title"),
                data.get("source_key"),
                principal_id,
                idempotency_key,
            )
            return facade_result(action, {**staged, "artifact": artifact, **result})
        if action == "attach_asset":
            data = strict_facade_payload(
                payload,
                action="module_import(attach_asset)",
                allowed={
                    "module_id",
                    "source_path",
                    "asset_kind",
                    "scene_id",
                    "location_key",
                    "title",
                    "metadata",
                },
                required_names=("module_id", "source_path", "asset_kind"),
            )
            return facade_result(
                action,
                module_asset_attach(
                    campaign_id,
                    required(data, "module_id"),
                    required(data, "source_path"),
                    asset_kind=required(data, "asset_kind"),
                    scene_id=data.get("scene_id"),
                    location_key=data.get("location_key"),
                    title=data.get("title"),
                    metadata=data.get("metadata"),
                    principal_id=principal_id,
                    idempotency_key=idempotency_key,
                ),
            )
        if action == "activate":
            data = strict_facade_payload(
                payload,
                action="module_import(activate)",
                allowed={"job_id", "progress_remaps"},
                required_names=("job_id",),
            )
        if action == "inspect":
            data = strict_facade_payload(
                payload,
                action="module_import(inspect)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                module_import_job_inspect(
                    campaign_id, data["job_id"], principal_id, idempotency_key
                ),
            )
        if action == "validate":
            data = strict_facade_payload(
                payload,
                action="module_import(validate)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                module_import_job_validate(
                    campaign_id, data["job_id"], principal_id, idempotency_key
                ),
            )
        if action == "ingest":
            data = strict_facade_payload(
                payload,
                action="module_import(ingest)",
                allowed={"job_id"},
                required_names=("job_id",),
            )
            return facade_result(
                action,
                module_import_job_import(
                    campaign_id, data["job_id"], principal_id, idempotency_key
                ),
            )
        return facade_result(
            action,
            module_import_job_activate(
                campaign_id,
                data["job_id"],
                principal_id,
                expected_revision,
                idempotency_key,
                data.get("progress_remaps"),
            ),
        )

    @mcp.tool()
    def module_review(
        campaign_id: str,
        action: Literal["render_page", "submit_content"],
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Render managed module evidence or submit a DM-only content review."""
        if action == "render_page":
            require_facade_phase(
                campaign_id,
                "module_review(render_page)",
                PROFILE_LOBBY,
                PROFILE_PLAY,
            )
            data = strict_facade_payload(
                payload,
                action="module_review(render_page)",
                allowed={
                    "module_id",
                    "page_number",
                    "source_asset_id",
                    "scale",
                },
                required_names=("module_id", "page_number"),
            )
            return facade_render_result(  # type: ignore[return-value]
                module_page_render(
                    campaign_id,
                    data["module_id"],
                    data["page_number"],
                    data.get("source_asset_id"),
                    data.get("scale", 1.5),
                    principal_id,
                )
            )
        require_facade_phase(
            campaign_id,
            "module_review(submit_content)",
            PROFILE_LOBBY,
        )
        data = strict_facade_payload(
            payload,
            action="module_review(submit_content)",
            allowed={
                "module_id",
                "scene_id",
                "content_key",
                "normalized_content",
                "observation",
                "source_asset_id",
                "page_number",
                "source_chunk_ids",
                "content_kind",
                "metadata",
                "agent_fill",
            },
            required_names=(
                "module_id",
                "scene_id",
                "content_key",
                "normalized_content",
                "observation",
            ),
        )
        content_kind = data.get("content_kind", "dnd5e_2014_statblock")
        if content_kind != "dnd5e_2014_statblock":
            raise ValueError("payload.content_kind must be dnd5e_2014_statblock")
        return facade_result(
            action,
            module_content_review(
                campaign_id,
                data["module_id"],
                data["scene_id"],
                data["content_key"],
                data["normalized_content"],
                data["observation"],
                data.get("source_asset_id"),
                data.get("page_number"),
                data.get("source_chunk_ids"),
                content_kind,
                data.get("metadata"),
                principal_id,
                idempotency_key,
                data.get("agent_fill"),
            ),
        )

    @mcp.tool()
    def module_query(
        campaign_id: str,
        view: Literal[
            "list",
            "index",
            "scene",
            "current",
            "progress",
            "readiness",
            "assets",
            "content",
            "candidates",
        ] = "list",
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read module cards, indexes, one scene, or current scoped progress."""
        data = facade_payload(payload)
        if view == "list":
            result = module_list(campaign_id, principal_id)
        elif view == "index":
            result = module_index(campaign_id, data.get("module_id"), principal_id)
        elif view == "scene":
            result = module_read_scene(
                campaign_id,
                required(data, "scene_id"),
                data.get("scope_id", "party"),
                principal_id,
            )
        elif view == "current":
            result = module_current(campaign_id, data.get("scope_id", "party"), principal_id)
        elif view == "readiness":
            result = module_scene_readiness(
                campaign_id,
                required(data, "scene_id"),
                required(data, "participant_manifest"),
                principal_id,
            )
        elif view == "assets":
            result = module_assets(campaign_id, required(data, "module_id"), principal_id)
        elif view == "content":
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            if data.get("review_id"):
                result = modules.get_content_review(campaign_id, str(data["review_id"]))
            else:
                result = modules.list_content_reviews(
                    campaign_id,
                    required(data, "module_id"),
                    content_kind=data.get("content_kind"),
                    content_key=data.get("content_key"),
                )
        elif view == "candidates":
            result = module_content_candidates(
                campaign_id,
                required(data, "module_id"),
                principal_id,
            )
        else:
            result = module_progress_index(
                campaign_id,
                data.get("scope_id", "party"),
                data.get("module_id"),
                principal_id,
            )
        return facade_result(view, result)

    @mcp.tool()
    def rule_pack_compile(
        action: Literal["draft", "from_source"],
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        """Compile a rule-pack draft, optionally bound to an indexed source."""
        data = facade_payload(payload)
        if action == "draft":
            result = rule_pack_draft(
                required(data, "manifest"),
                data.get("artifacts"),
                data.get("mechanics"),
                data.get("provenance"),
            )
        else:
            result = rule_pack_draft_from_source(
                required(data, "source_id"),
                required(data, "manifest"),
                data.get("artifacts"),
                data.get("mechanics"),
                data.get("provenance"),
            )
        return facade_result(action, result)

    @mcp.tool()
    def rule_pack_query(
        view: Literal[
            "list",
            "inspect",
            "test",
            "content_catalog",
            "sources",
            "source_chunks",
        ] = "list",
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """List, inspect, test, or browse selection-ready rule-pack content."""
        data = facade_payload(payload)
        if view == "list":
            result = rule_pack_list(data.get("pack_id"))
        elif view == "inspect":
            result = rule_pack_inspect(required(data, "pack_id"), required(data, "version"))
        elif view == "test":
            result = rule_pack_test(required(data, "pack_id"), required(data, "version"))
        elif view == "content_catalog":
            result = content_catalog_list(
                required(data, "campaign_id"),
                data.get("kind"),
                data.get("query", ""),
                principal_id,
                data.get("branch_id"),
            )
        elif view == "sources":
            result = rules.sources(
                system_id=data.get("system_id", DND5E.id),
                edition=data.get("edition"),
            )
        else:
            source_id = str(required(data, "source_id"))
            source = rules.source(source_id)
            if str(source.get("system_id") or "") != DND5E.id:
                raise ValueError("rule source must belong to the dnd5e rule corpus")
            page = data.get("page")
            if page is not None and (
                isinstance(page, bool) or not isinstance(page, int) or page < 1
            ):
                raise ValueError("payload.page must be a positive integer")
            query = str(data.get("query") or "").strip().casefold()
            limit = data.get("limit", 50)
            if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 200:
                raise ValueError("payload.limit must be an integer between 1 and 200")
            chunks = rules.source_chunks(source_id)
            if page is not None:
                chunks = [
                    item
                    for item in chunks
                    if isinstance(item.get("page_start"), int)
                    and isinstance(item.get("page_end"), int)
                    and int(item["page_start"]) <= page <= int(item["page_end"])
                ]
            if query:
                chunks = [
                    item
                    for item in chunks
                    if query
                    in "\n".join(
                        [
                            *[str(value) for value in item.get("heading_path", [])],
                            str(item.get("content") or ""),
                        ]
                    ).casefold()
                ]
            result = chunks[:limit]
        return facade_result(view, result)

    @mcp.tool()
    def rule_pack_change(
        action: Literal["install", "remove"],
        pack_id: str,
        version: str,
    ) -> dict[str, Any]:
        """Install or remove a locally compiled rule-pack version."""
        result = (
            rule_pack_install(pack_id, version)
            if action == "install"
            else rule_pack_remove(pack_id, version)
        )
        return facade_result(action, result)

    @mcp.tool()
    def campaign_rules(
        campaign_id: str,
        action: Literal[
            "get_profile",
            "set_profile",
            "set_pack",
            "remove_pack",
            "core_relock",
            "explain",
            "receipts",
        ],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Read and change the campaign rule profile and enabled pack set."""
        data = facade_payload(payload)
        if action == "get_profile":
            result = campaign_rule_profile_get(campaign_id, principal_id)
        elif action == "set_profile":
            result = campaign_rule_profile_set(
                campaign_id,
                required(data, "edition"),
                data.get("locale", "en"),
                data.get("publications"),
                data.get("options"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "set_pack":
            result = campaign_rule_pack_set(
                campaign_id,
                required(data, "pack_id"),
                required(data, "version"),
                data.get("enabled", True),
                data.get("options"),
                principal_id,
                branch_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "remove_pack":
            result = campaign_rule_pack_remove(
                campaign_id,
                required(data, "pack_id"),
                principal_id,
                branch_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "core_relock":
            data = strict_facade_payload(
                payload,
                action="campaign_rules(core_relock)",
                allowed={
                    "expected_core_fingerprint",
                    "reason",
                    "expected_head_snapshot_id",
                },
                required_names=(
                    "expected_core_fingerprint",
                    "reason",
                    "expected_head_snapshot_id",
                ),
            )
            result = campaign_core_relock(
                campaign_id,
                data["expected_core_fingerprint"],
                data["reason"],
                principal_id,
                branch_id,
                expected_revision,
                data["expected_head_snapshot_id"],
                idempotency_key,
            )
        elif action == "explain":
            result = campaign_rules_explain(campaign_id, data.get("event"), principal_id, branch_id)
        else:
            result = campaign_rule_receipts(
                campaign_id,
                principal_id,
                branch_id,
                data.get("mechanic_id"),
                data.get("limit", 100),
            )
        return facade_result(action, result)

    @mcp.tool()
    @_agent_ruling_boundary
    def character_query(
        view: Literal[
            "get",
            "batch",
            "list",
            "library",
            "document",
            "rest",
            "advancement",
        ] = "list",
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read characters or inspect an allowlisted character document without inventing data."""
        data = facade_payload(payload)
        if view == "get":
            result = character_get(required(data, "character_id"), principal_id)
        elif view == "batch":
            campaign_id = str(required(data, "campaign_id"))
            actor_ids_value = data.get("character_ids")
            if not isinstance(actor_ids_value, list) or not actor_ids_value:
                raise ValueError("batch character query requires a non-empty character_ids list")
            actor_ids = [str(item).strip() for item in actor_ids_value]
            if (
                len(actor_ids) > 100
                or any(not item for item in actor_ids)
                or len(actor_ids) != len(set(actor_ids))
            ):
                raise ValueError(
                    "batch character query requires 1-100 unique non-empty character_ids"
                )
            membership = access.require_campaign(campaign_id, principal_id)
            campaign_characters = {
                item.id: item
                for item in characters.list(system_id=DND5E.id, campaign_id=campaign_id)
            }
            missing = [actor_id for actor_id in actor_ids if actor_id not in campaign_characters]
            if missing:
                raise ValueError(
                    "batch character query includes actors outside the campaign: "
                    + ", ".join(missing)
                )
            selected = [campaign_characters[actor_id] for actor_id in actor_ids]
            if membership.role in CAMPAIGN_DM_ROLES:
                rules_context = effective_rule_context(campaign_id)
                result = [
                    character_view(character, rules_context=rules_context) for character in selected
                ]
            else:
                result = [visible_character_view(character, principal_id) for character in selected]
        elif view == "advancement":
            result = character_level_advancement_plan(
                str(required(data, "character_id")),
                str(required(data, "class_name")),
                principal_id,
            )
        elif view == "rest":
            character_id = str(required(data, "character_id"))
            current = characters.get(character_id)
            require_character_control(current, principal_id)
            require_outside_active_combat(current, "rest preflight")
            if current.campaign_id is None:
                raise ValueError("rest preflight requires a campaign-bound character")
            campaign = campaigns.get(current.campaign_id)
            if bool(dict(dict(campaign.state or {}).get("combat") or {}).get("active")):
                raise CombatEngineError("rest is not allowed while combat is active")
            rest_type = str(data.get("rest_type") or "").strip().lower().replace("-", "_")
            if rest_type != "short_rest":
                raise CombatEngineError(
                    "character rest preflight currently requires rest_type=short_rest"
                )
            hp = int(dict(current.sheet.get("combat", {}).get("hp") or {}).get("value", 0) or 0)
            conditions = {str(item).casefold() for item in current.sheet.get("conditions", [])}
            if hp <= 0 or "dead" in conditions:
                raise CombatEngineError(
                    "a creature at 0 hit points or dead cannot benefit from a rest"
                )
            hit_dice = validate_rest_hit_dice_requests(current.sheet, data.get("hit_dice_spends"))
            game_day = rules_day_from_ticks(
                int(
                    dict(dict(campaign.state or {}).get("game_time") or {}).get(
                        "elapsed_ticks",
                        0,
                    )
                    or 0
                )
            )
            arcane_recovery = validate_arcane_recovery_choice(
                current.sheet,
                data.get("arcane_recovery"),
                game_day=game_day,
            )
            natural_recovery = validate_natural_recovery_choice(
                current.sheet,
                data.get("natural_recovery"),
                rest_activity_minutes=data.get("rest_activity_minutes"),
            )
            song_source_actor_id = (
                str(data.get("song_of_rest_source_actor_id") or "").strip() or None
            )
            song_die_sides = None
            if song_source_actor_id is not None:
                song_source = characters.get(song_source_actor_id)
                if song_source.campaign_id != current.campaign_id:
                    raise CombatEngineError(
                        "Song of Rest source must belong to the resting character's campaign"
                    )
                song_die_sides = validate_song_of_rest_source(song_source.sheet)
            rest_activity_minutes = validate_rest_activity_minutes(
                data.get("rest_activity_minutes")
            )
            attune_item_id = str(data.get("attune_item_id") or "").strip() or None
            if attune_item_id is not None:
                if data.get("attunement_prerequisite_confirmed") is not True:
                    raise NeedsRulingError(
                        "attunement requires explicit DM confirmation that the actor "
                        "satisfies every source-defined prerequisite",
                        missing=("attunement_prerequisite",),
                        ruling_kind="source_or_scene_fact",
                    )
                if not is_dm(current.campaign_id, principal_id):
                    raise PermissionError(
                        "attunement prerequisite confirmation requires the Agent in the DM role"
                    )
                attune_inventory_item(current.sheet, attune_item_id)
            elif data.get("attunement_prerequisite_confirmed") is not None:
                raise CombatEngineError("attunement_prerequisite_confirmed requires attune_item_id")
            duration_minutes = data.get("duration_minutes")
            if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
                raise CombatEngineError("short rest preflight requires duration_minutes")
            rest_schedule = validate_rest_schedule(
                rest_type=rest_type,
                duration_minutes=duration_minutes,
                rest_schedule=data.get("rest_schedule"),
            )
            rest_rules = effective_rule_context(
                current.campaign_id,
                facts={"actor_id": current.id, "rest_type": rest_type},
            )
            before_rules = apply_rule_event(current.sheet, "rest.before", rest_rules)
            result = {
                "ready": before_rules.status == "committed",
                "character_id": current.id,
                "character_revision": current.revision,
                "campaign_id": current.campaign_id,
                "rest_type": rest_type,
                "game_day": game_day,
                "hit_dice_spends": [{"key": key, "count": count} for key, count in hit_dice],
                "arcane_recovery": arcane_recovery,
                "natural_recovery": natural_recovery,
                "song_of_rest_source_actor_id": song_source_actor_id,
                "song_of_rest_die": (f"1d{song_die_sides}" if song_die_sides is not None else None),
                "attune_item_id": attune_item_id,
                "attunement_prerequisite_confirmed": (True if attune_item_id is not None else None),
                "rest_activity_minutes": rest_activity_minutes,
                "rest_schedule": rest_schedule,
                "pending": list(before_rules.pending),
                "ruleset_fingerprint": rest_rules.fingerprint,
            }
        elif view == "library":
            result = character_library_list(data.get("character_type"), principal_id)
        elif view == "document":
            campaign_id = str(required(data, "campaign_id"))
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            staged = storage.stage_module(str(required(data, "source_path")))
            expected_checksum = str(data.get("expected_checksum") or "").strip()
            if expected_checksum and expected_checksum != staged["checksum"]:
                raise ValueError("character document checksum does not match expected_checksum")
            document = normalize_document(
                staged["path"],
                ocr_provider=storage.module_ocr_provider(),
                cache_dir=config.normalized_modules_dir,
                expected_checksum=str(staged["checksum"]),
            )
            inspection = inspect_character_document(
                document,
                source_name=Path(str(data["source_path"])).name,
            )
            result = {
                **inspection,
                "artifact": {
                    key: value for key, value in staged.items() if key not in {"path", "staged"}
                },
                "workflow": {
                    "next": (
                        "complete_missing_fields_then_character_create_from"
                        if not inspection["ready_to_create"]
                        else "character_create_from"
                    ),
                    "creation_tool": "character_create_from(mode='build')",
                    "content_tool": "character_content_apply",
                    "module_import_allowed": False,
                },
            }
        else:
            result = character_list(data.get("campaign_id"), principal_id)
        return facade_result(view, result)

    @mcp.tool()
    def character_create_from(
        mode: Literal[
            "direct",
            "build",
            "template",
            "statblock",
            "reviewed_rule_statblock",
            "module_statblock",
            "narrative_npc",
        ],
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Create directly, by build/template, or from source-bound module evidence."""
        data = facade_payload(payload)
        if mode == "direct":
            result = character_create(
                required(data, "name"),
                data.get("campaign_id"),
                data.get("character_type", "pc"),
                data.get("player_name"),
                data.get("summary", ""),
                data.get("sheet"),
                data.get("notes"),
                principal_id,
                idempotency_key,
            )
        elif mode == "narrative_npc":
            campaign_id = str(required(data, "campaign_id"))
            name = str(required(data, "name")).strip()
            role = str(required(data, "role")).strip()
            summary = str(required(data, "summary")).strip()
            source_identity = str(data.get("source_identity") or name).strip()
            instance_key = str(data.get("instance_key") or "").strip()
            identity_agent_ruling_raw = data.get("identity_agent_ruling")
            identity_agent_ruling: dict[str, Any] | None = None
            source_ref = data.get("source_ref")
            source_excerpt = " ".join(str(required(data, "source_excerpt")).split()).strip()
            if not name or len(name) > 200:
                raise ValueError("narrative NPC name must contain 1 to 200 characters")
            if not source_identity or len(source_identity) > 200:
                raise ValueError("narrative NPC source_identity must contain 1 to 200 characters")
            if len(instance_key) > 100:
                raise ValueError("narrative NPC instance_key must not exceed 100 characters")
            if identity_agent_ruling_raw is not None:
                if not isinstance(identity_agent_ruling_raw, dict):
                    raise ValueError("narrative NPC identity_agent_ruling must be an object")
                allowed_ruling_fields = {
                    "default_resolver",
                    "ruling_kind",
                    "decision",
                    "reason",
                    "assigned_name",
                    "source_identity",
                    "instance_key",
                    "committed",
                }
                unknown_ruling_fields = sorted(
                    set(identity_agent_ruling_raw) - allowed_ruling_fields
                )
                if unknown_ruling_fields:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling contains unsupported "
                        "fields: " + ", ".join(unknown_ruling_fields)
                    )
                if identity_agent_ruling_raw.get("default_resolver") != "agent":
                    raise ValueError(
                        "narrative NPC identity_agent_ruling default_resolver must be agent"
                    )
                if (
                    str(identity_agent_ruling_raw.get("ruling_kind") or "")
                    != "agent_dm_adjudication"
                ):
                    raise ValueError(
                        "narrative NPC identity_agent_ruling ruling_kind must be "
                        "agent_dm_adjudication"
                    )
                decision = str(identity_agent_ruling_raw.get("decision") or "").strip()
                reason = str(identity_agent_ruling_raw.get("reason") or "").strip()
                if not decision or len(decision) > 1_000:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling decision must contain "
                        "1 to 1000 characters"
                    )
                if not reason or len(reason) > 500:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling reason must contain "
                        "1 to 500 characters"
                    )
                if identity_agent_ruling_raw.get("committed") is not True:
                    raise ValueError("narrative NPC identity_agent_ruling must be committed")
                if not instance_key:
                    raise ValueError("Agent-named narrative NPCs require a source instance_key")
                if str(identity_agent_ruling_raw.get("assigned_name") or "") != name:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling assigned_name must match name"
                    )
                if str(identity_agent_ruling_raw.get("source_identity") or "") != source_identity:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling source_identity must "
                        "match source_identity"
                    )
                if str(identity_agent_ruling_raw.get("instance_key") or "") != instance_key:
                    raise ValueError(
                        "narrative NPC identity_agent_ruling instance_key must match instance_key"
                    )
                identity_agent_ruling = {
                    "default_resolver": "agent",
                    "ruling_kind": "agent_dm_adjudication",
                    "decision": decision,
                    "reason": reason,
                    "assigned_name": name,
                    "source_identity": source_identity,
                    "instance_key": instance_key,
                    "committed": True,
                }
            elif instance_key:
                expected_instance_name = f"{source_identity} [{instance_key}]"
                if name != expected_instance_name:
                    raise ValueError(
                        "anonymous narrative NPC name must equal "
                        "'<source_identity> [<instance_key>]'"
                    )
            elif source_identity != name:
                raise ValueError(
                    "narrative NPC source_identity may differ from name only "
                    "when instance_key is provided"
                )
            if not role or len(role) > 500:
                raise ValueError("narrative NPC role must contain 1 to 500 characters")
            if not summary or len(summary) > 2000:
                raise ValueError("narrative NPC summary must contain 1 to 2000 characters")
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            campaign = campaigns.get(campaign_id)
            if authoritative_phase(campaign_id) != PROFILE_LOBBY:
                raise CombatEngineError("narrative NPCs can be created only in lobby")
            _, normalized_source_ref, expanded = managed_module_source_ref(
                campaign_id,
                source_ref,
                require_exact=True,
                require_active_module=True,
            )
            if normalized_source_ref is None or expanded is None:
                raise AssertionError(
                    "exact narrative NPC citations always resolve to a managed chunk"
                )
            chunk_content = str(expanded.get("content") or "")
            normalized_source_excerpt = managed_module_source_excerpt(
                expanded,
                source_excerpt,
                field="narrative NPC source_excerpt",
                minimum_length=8,
            )
            if not _source_contains_narrative_name(
                name=source_identity,
                content=chunk_content,
            ):
                raise ValueError("narrative NPC name is not present in its source chunk")

            evidence = {
                "kind": "source_bound_narrative_npc",
                "role": role,
                "combat_statblock": "not_imported",
                "source_ref": normalized_source_ref,
                "source_excerpt": normalized_source_excerpt,
                **(
                    {
                        "source_identity": source_identity,
                        "instance_key": instance_key,
                    }
                    if instance_key
                    else {}
                ),
                **(
                    {"identity_agent_ruling": identity_agent_ruling}
                    if identity_agent_ruling is not None
                    else {}
                ),
            }
            sheet = default_character_sheet()
            sheet["adventure_state"]["status_tags"] = [
                "narrative_only",
                "source_bound",
                *(["anonymous_source_instance"] if instance_key else []),
                *(["agent_named_source_instance"] if identity_agent_ruling is not None else []),
            ]
            notes = default_character_notes()
            notes["profile"]["summary"] = role
            notes["profile"]["dm_notes"] = (
                "sagasmith:narrative-npc-source:" + canonical_json(evidence)
            )
            character = character_create(
                name,
                campaign_id,
                "npc",
                None,
                summary,
                sheet,
                notes,
                principal_id,
                idempotency_key,
            )
            result = {
                "character": character,
                "narrative_npc": {
                    **evidence,
                    "combat_eligible": False,
                },
            }
        elif mode == "build":
            result = character_build(
                required(data, "campaign_id"),
                required(data, "name"),
                data.get("player_name"),
                data.get("summary", ""),
                data.get("sheet"),
                data.get("notes"),
                principal_id,
                idempotency_key,
            )
        elif mode == "template":
            result = character_instantiate(
                required(data, "template_id"),
                required(data, "campaign_id"),
                data.get("name"),
                data.get("player_name"),
                principal_id,
            )
        elif mode == "reviewed_rule_statblock":
            campaign_id = str(required(data, "campaign_id"))
            job_id = str(required(data, "job_id"))
            review_id = str(required(data, "review_id"))
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            job = require_import_job(campaign_id, job_id, "rulebook")
            reviews = list(dict(job.result or {}).get("statblock_reviews") or [])
            matches = [item for item in reviews if str(item.get("id") or "") == review_id]
            if len(matches) != 1:
                raise ValueError("reviewed rule statblock does not belong to the import job")
            review = dict(matches[0])
            if str(review.get("source_id") or "") != str(job.source_id or ""):
                raise ValueError("reviewed rule statblock source no longer matches its import job")
            content = str(review.get("normalized_content") or "")
            if hashlib.sha256(content.encode("utf-8")).hexdigest() != str(
                review.get("normalized_content_sha256") or ""
            ):
                raise ValueError("reviewed rule statblock content checksum is invalid")
            campaign = campaigns.get(campaign_id)
            source = rules.source(str(job.source_id))
            if (
                campaign_rules_edition(campaign.id) != "2014"
                or str(source.get("edition") or "") != "2014"
            ):
                raise ValueError("reviewed rule statblocks require a D&D 2014 campaign and source")
            source_key = f"rule-review:{review_id}"
            source_rule_refs = [
                f"rule-source:{job.source_id}",
                f"rule-source-page:{job.source_id}:{review['page_number']}",
                f"rule-review:{review_id}",
            ]
            parsed = parse_2014_statblock(
                content,
                source_key=source_key,
                rule_refs=source_rule_refs,
                name=str(data.get("name") or "").strip() or None,
            )
            hydrated_sheet, spell_warnings = hydrate_statblock_spellcasting(
                campaign_id,
                parsed,
                source_key=source_key,
                rule_refs=source_rule_refs,
            )
            reviewed_fill = review.get("agent_statblock_fill")
            require_standard_statblock_engine_support(
                hydrated_sheet,
                reviewed_fill,
            )
            filled = (
                apply_reviewed_statblock_fill(hydrated_sheet, reviewed_fill)
                if reviewed_fill is not None
                else None
            )
            if filled is not None:
                hydrated_sheet = filled["sheet"]
            variant = data.get("variant")
            variant_evidence = statblock_variant_evidence(campaign_id, variant)
            hydrated_sheet = hydrate_statblock_variant_spells(
                campaign_id,
                hydrated_sheet,
                variant,
            )
            statblock_warnings = retained_statblock_warnings(
                [*parsed.warnings, *spell_warnings],
                variant,
            )
            statblock_normalization_notes = retained_statblock_warnings(
                list(parsed.normalization_notes),
                variant,
            )
            resolved_fill_warnings = set((filled or {}).get("resolved_warnings") or [])
            statblock_warnings = [
                warning for warning in statblock_warnings if warning not in resolved_fill_warnings
            ]
            statblock_warnings = list(
                dict.fromkeys(
                    [
                        *statblock_warnings,
                        *((filled or {}).get("added_warnings") or []),
                    ]
                )
            )
            sheet = (
                apply_statblock_variant(hydrated_sheet, variant)
                if variant is not None
                else hydrated_sheet
            )
            challenge_rating, experience_points = effective_statblock_rating(
                parsed.challenge_rating,
                parsed.experience_points,
                variant,
            )
            character_type = str(data.get("character_type") or "monster")
            if character_type not in NON_PLAYER_CHARACTER_TYPES:
                raise ValueError(
                    "reviewed rule statblock import creates only npc or monster actors"
                )
            notes = source_bound_statblock_notes(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
            )
            profile = notes.setdefault("profile", {})
            if not str(profile.get("summary") or "").strip():
                profile["summary"] = parsed.summary
            provenance = (
                f"Reviewed rule statblock: rule-source:{job.source_id} "
                f"(review_id={review_id}; page={review['page_number']}; "
                f"asset_checksum={review['asset_checksum']}; "
                f"image_checksum={review['image_checksum']})."
            )
            if variant is not None:
                changed_fields = (
                    ", ".join(sorted(set(variant) - {"source_ref", "source_refs"})) or "none"
                )
                provenance += (
                    f"\nVariant source: {statblock_variant_source_label(variant)}; "
                    f"applied fields: {changed_fields}."
                )
            provenance = append_statblock_diagnostics(
                provenance,
                warnings=statblock_warnings,
                normalization_notes=statblock_normalization_notes,
            )
            if filled is not None:
                fill_labels = reviewed_statblock_fill_labels(filled["fill"])
                provenance += (
                    "\nAgent statblock fill: "
                    + ", ".join(fill_labels)
                    + "."
                )
            existing_dm_notes = str(profile.get("dm_notes") or "").strip()
            profile["dm_notes"] = "\n".join(
                item for item in (existing_dm_notes, provenance) if item
            )
            character = persist_source_bound_statblock(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
                name=parsed.name,
                summary=source_bound_statblock_summary(
                    data=data,
                    campaign_id=campaign_id,
                    character_type=character_type,
                    fallback=parsed.summary,
                ),
                sheet=sheet,
                notes=notes,
                principal_id=principal_id,
                idempotency_key=idempotency_key,
            )
            result = {
                "character": character,
                "source": {
                    key: value for key, value in review.items() if key != "normalized_content"
                },
                "statblock": {
                    "challenge_rating": challenge_rating,
                    "experience_points": experience_points,
                    **statblock_settlement(
                        statblock_warnings,
                        normalization_notes=statblock_normalization_notes,
                    ),
                    "agent_fill": (filled or {}).get("fill"),
                },
                "variant": deepcopy(variant) if variant is not None else None,
                "variant_evidence": variant_evidence,
            }
        elif mode == "module_statblock":
            campaign_id = str(required(data, "campaign_id"))
            review_id = str(required(data, "review_id"))
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            campaign = campaigns.get(campaign_id)
            campaign_edition = campaign_rules_edition(campaign.id)
            if campaign_edition != "2014":
                raise ValueError("reviewed module statblocks currently support D&D 2014 campaigns")
            review = modules.get_content_review(campaign_id, review_id)
            if review["content_kind"] != "dnd5e_2014_statblock":
                raise ValueError("module content review is not a D&D 2014 statblock")
            parsed = parse_2014_statblock(
                review["normalized_content"],
                source_key=f"module-review:{review_id}",
                rule_refs=[f"module-scene:{review['scene_id']}", f"module-review:{review_id}"],
                name=str(data.get("name") or "").strip() or None,
            )
            source_key = f"module-review:{review_id}"
            source_rule_refs = [
                f"module-scene:{review['scene_id']}",
                f"module-review:{review_id}",
            ]
            hydrated_sheet, spell_warnings = hydrate_statblock_spellcasting(
                campaign_id,
                parsed,
                source_key=source_key,
                rule_refs=source_rule_refs,
            )
            reviewed_fill = dict(review.get("metadata") or {}).get("agent_statblock_fill")
            require_complete_statblock_agent_fill(
                hydrated_sheet,
                reviewed_fill,
            )
            filled = (
                apply_reviewed_statblock_fill(hydrated_sheet, reviewed_fill)
                if reviewed_fill is not None
                else None
            )
            if filled is not None:
                hydrated_sheet = filled["sheet"]
            variant = data.get("variant")
            variant_evidence = statblock_variant_evidence(campaign_id, variant)
            hydrated_sheet = hydrate_statblock_variant_spells(
                campaign_id,
                hydrated_sheet,
                variant,
            )
            statblock_warnings = retained_statblock_warnings(
                [*parsed.warnings, *spell_warnings],
                variant,
            )
            statblock_normalization_notes = retained_statblock_warnings(
                list(parsed.normalization_notes),
                variant,
            )
            resolved_fill_warnings = set((filled or {}).get("resolved_warnings") or [])
            statblock_warnings = [
                warning for warning in statblock_warnings if warning not in resolved_fill_warnings
            ]
            statblock_warnings = list(
                dict.fromkeys(
                    [
                        *statblock_warnings,
                        *((filled or {}).get("added_warnings") or []),
                    ]
                )
            )
            sheet = (
                apply_statblock_variant(hydrated_sheet, variant)
                if variant is not None
                else hydrated_sheet
            )
            challenge_rating, experience_points = effective_statblock_rating(
                parsed.challenge_rating,
                parsed.experience_points,
                variant,
            )
            character_type = str(data.get("character_type") or "monster")
            if character_type not in NON_PLAYER_CHARACTER_TYPES:
                raise ValueError("module statblock import creates only npc or monster actors")
            notes = source_bound_statblock_notes(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
            )
            profile = notes.setdefault("profile", {})
            if not str(profile.get("summary") or "").strip():
                profile["summary"] = parsed.summary
            evidence = dict(review.get("evidence") or {})
            provenance = (
                f"Reviewed module statblock: module-review:{review_id} "
                f"(module_id={review['module_id']}; scene_id={review['scene_id']}; "
                f"page={evidence.get('page')}; asset_checksum={evidence.get('asset_checksum')})."
            )
            if variant is not None:
                changed_fields = (
                    ", ".join(sorted(set(variant) - {"source_ref", "source_refs"})) or "none"
                )
                provenance += (
                    f"\nVariant source: {statblock_variant_source_label(variant)}; "
                    "applied fields: "
                    f"{changed_fields}."
                )
            provenance = append_statblock_diagnostics(
                provenance,
                warnings=statblock_warnings,
                normalization_notes=statblock_normalization_notes,
            )
            if filled is not None:
                fill_labels = reviewed_statblock_fill_labels(filled["fill"])
                provenance += (
                    "\nAgent statblock fill: "
                    + ", ".join(fill_labels)
                    + "."
                )
            existing_dm_notes = str(profile.get("dm_notes") or "").strip()
            profile["dm_notes"] = "\n".join(
                item for item in (existing_dm_notes, provenance) if item
            )
            character = persist_source_bound_statblock(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
                name=parsed.name,
                summary=source_bound_statblock_summary(
                    data=data,
                    campaign_id=campaign_id,
                    character_type=character_type,
                    fallback=parsed.summary,
                ),
                sheet=sheet,
                notes=notes,
                principal_id=principal_id,
                idempotency_key=idempotency_key,
            )
            result = {
                "character": character,
                "source": review,
                "statblock": {
                    "challenge_rating": challenge_rating,
                    "experience_points": experience_points,
                    **statblock_settlement(
                        statblock_warnings,
                        normalization_notes=statblock_normalization_notes,
                    ),
                    "agent_fill": (filled or {}).get("fill"),
                },
                "variant": deepcopy(variant) if variant is not None else None,
                "variant_evidence": variant_evidence,
            }
        else:
            campaign_id = str(required(data, "campaign_id"))
            source_id = str(required(data, "source_id"))
            access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
            campaign = campaigns.get(campaign_id)
            source = rules.source(source_id)
            if str(source.get("system_id") or "") != DND5E.id:
                raise ValueError("statblock source must belong to the dnd5e rule corpus")
            campaign_edition = campaign_rules_edition(campaign.id)
            source_edition = str(source.get("edition") or "")
            if source_edition != campaign_edition:
                raise ValueError(
                    f"statblock source edition {source_edition!r} does not match "
                    f"campaign edition {campaign_edition!r}"
                )
            if source_edition != "2014":
                raise ValueError("structured statblock import currently supports D&D 2014 sources")

            available_chunks = rules.source_chunks(source_id)
            by_chunk_id = {str(item["id"]): item for item in available_chunks}
            selected_value = data.get("chunk_ids")
            if selected_value is None:
                selected_chunks = available_chunks
            else:
                if not isinstance(selected_value, list):
                    raise ValueError("payload.chunk_ids must be a list")
                chunk_ids = [str(item).strip() for item in selected_value]
                if any(not item for item in chunk_ids) or len(chunk_ids) != len(set(chunk_ids)):
                    raise ValueError("payload.chunk_ids must contain unique non-empty ids")
                missing = [item for item in chunk_ids if item not in by_chunk_id]
                if missing:
                    raise ValueError("statblock chunks do not belong to the requested source")
                selected_chunks = [by_chunk_id[item] for item in chunk_ids]
            if not selected_chunks:
                raise ValueError("statblock source has no indexed chunks")
            selected_chunks = sorted(
                selected_chunks, key=lambda item: (int(item.get("ordinal", 0)), str(item["id"]))
            )
            selected_chunk_ids = [str(item["id"]) for item in selected_chunks]
            rendered_chunks = []
            for item in selected_chunks:
                heading_path = [
                    str(value).strip()
                    for value in item.get("heading_path", [])
                    if str(value).strip()
                ]
                headings = "\n".join(
                    f"{'#' * min(6, 3 + index)} {heading}"
                    for index, heading in enumerate(heading_path)
                )
                rendered_chunks.append(
                    "\n\n".join(
                        value for value in (headings, str(item.get("content") or "")) if value
                    )
                )
            source_text = "\n\n".join(rendered_chunks)
            actor_name = str(data.get("name") or source.get("title") or "").strip()
            source_statblock_name = str(data.get("source_statblock_name") or "").strip()
            if source_statblock_name and not 2 <= len(source_statblock_name) <= 200:
                raise ValueError("payload.source_statblock_name must contain 2 to 200 characters")
            text_layout_recovery: dict[str, Any] | None = None
            try:
                parsed = parse_2014_statblock(
                    source_text,
                    source_key=f"rule-source:{source['source_key']}",
                    rule_refs=selected_chunk_ids,
                    name=actor_name or None,
                )
            except StatblockImportError:
                if not source_statblock_name:
                    raise
                recovered_candidate = normalize_2014_statblock_candidate(
                    source_statblock_name,
                    selected_chunks,
                )
                recovered_chunk_ids = list(recovered_candidate["source_chunk_ids"])
                selected_chunks = [by_chunk_id[item] for item in recovered_chunk_ids]
                selected_chunk_ids = recovered_chunk_ids
                source_text = str(recovered_candidate["normalized_content"])
                parsed = parse_2014_statblock(
                    source_text,
                    source_key=f"rule-source:{source['source_key']}",
                    rule_refs=selected_chunk_ids,
                    name=actor_name or None,
                )
                text_layout_recovery = {
                    "profile": "deterministic-text-layout-v1",
                    "source_statblock_name": source_statblock_name,
                    "chunk_ids": selected_chunk_ids,
                }
            source_key = f"rule-source:{source['source_key']}"
            hydrated_sheet, spell_warnings = hydrate_statblock_spellcasting(
                campaign_id,
                parsed,
                source_key=source_key,
                rule_refs=selected_chunk_ids,
            )
            require_standard_statblock_engine_support(
                hydrated_sheet,
                None,
            )
            variant = data.get("variant")
            variant_evidence = statblock_variant_evidence(campaign_id, variant)
            hydrated_sheet = hydrate_statblock_variant_spells(
                campaign_id,
                hydrated_sheet,
                variant,
            )
            statblock_warnings = retained_statblock_warnings(
                [*parsed.warnings, *spell_warnings],
                variant,
            )
            statblock_normalization_notes = retained_statblock_warnings(
                list(parsed.normalization_notes),
                variant,
            )
            sheet = (
                apply_statblock_variant(hydrated_sheet, variant)
                if variant is not None
                else hydrated_sheet
            )
            challenge_rating, experience_points = effective_statblock_rating(
                parsed.challenge_rating,
                parsed.experience_points,
                variant,
            )
            character_type = str(data.get("character_type") or "npc")
            if character_type not in NON_PLAYER_CHARACTER_TYPES:
                raise ValueError("statblock import creates only npc or monster actors")
            notes = source_bound_statblock_notes(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
            )
            profile = notes.setdefault("profile", {})
            if not str(profile.get("summary") or "").strip():
                profile["summary"] = parsed.summary
            provenance = (
                f"Statblock import: rule-source:{source['source_key']} "
                f"(source_id={source_id}; chunks={','.join(selected_chunk_ids)})."
            )
            if text_layout_recovery is not None:
                provenance += (
                    "\nText-layout recovery: "
                    f"{text_layout_recovery['profile']} "
                    f"(printed heading={source_statblock_name})."
                )
            if variant is not None:
                changed_fields = (
                    ", ".join(sorted(set(variant) - {"source_ref", "source_refs"})) or "none"
                )
                provenance += (
                    f"\nVariant source: {statblock_variant_source_label(variant)}; "
                    "applied fields: "
                    f"{changed_fields}."
                )
            provenance = append_statblock_diagnostics(
                provenance,
                warnings=statblock_warnings,
                normalization_notes=statblock_normalization_notes,
            )
            existing_dm_notes = str(profile.get("dm_notes") or "").strip()
            profile["dm_notes"] = "\n".join(
                item for item in (existing_dm_notes, provenance) if item
            )
            character = persist_source_bound_statblock(
                data=data,
                campaign_id=campaign_id,
                character_type=character_type,
                name=parsed.name,
                summary=source_bound_statblock_summary(
                    data=data,
                    campaign_id=campaign_id,
                    character_type=character_type,
                    fallback=parsed.summary,
                ),
                sheet=sheet,
                notes=notes,
                principal_id=principal_id,
                idempotency_key=idempotency_key,
            )
            result = {
                "character": character,
                "source": {
                    "id": source_id,
                    "source_key": source["source_key"],
                    "title": source["title"],
                    "edition": source_edition,
                    "checksum": source["checksum"],
                    "chunk_ids": selected_chunk_ids,
                    "text_layout_recovery": text_layout_recovery,
                },
                "statblock": {
                    "challenge_rating": challenge_rating,
                    "experience_points": experience_points,
                    **statblock_settlement(
                        statblock_warnings,
                        normalization_notes=statblock_normalization_notes,
                    ),
                },
                "variant": deepcopy(variant) if variant is not None else None,
                "variant_evidence": variant_evidence,
            }
        return facade_result(mode, result)

    @mcp.tool()
    def character_metadata_update(
        character_id: str,
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Update identity and notes metadata; whole-sheet changes remain separate."""
        data = facade_payload(payload)
        prohibited = {"sheet", "state", "derived"} & set(data)
        if prohibited:
            raise ValueError(
                f"character metadata update cannot change: {', '.join(sorted(prohibited))}"
            )
        if not any(name in data for name in ("name", "player_name", "summary", "notes")):
            raise ValueError("payload must include at least one metadata field")
        result = character_update(
            character_id,
            data.get("name"),
            data.get("player_name"),
            data.get("summary"),
            None,
            data.get("notes"),
            principal_id,
            expected_revision,
            idempotency_key,
        )
        return facade_result("metadata", result)

    @mcp.tool()
    def character_content_apply(
        character_id: str,
        artifact_id: str,
        selection: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Apply a selection-ready class, background, feat, spell, or feature artifact."""
        return facade_result(
            "apply",
            character_content_apply_legacy(
                character_id,
                artifact_id,
                selection,
                principal_id,
                expected_revision,
                idempotency_key,
            ),
        )

    @mcp.tool()
    def inventory_change(
        owner: Literal["character", "party"],
        action: Literal[
            "add",
            "update",
            "remove",
            "equip",
            "recharge",
            "consume_ammunition",
        ],
        owner_id: str,
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Change one character or party inventory while preserving owner-specific validation."""
        data = facade_payload(payload)
        if owner == "party" and action not in {"add", "remove"}:
            raise ValueError("party inventory supports only add and remove")
        if owner == "character":
            if action == "add":
                current = characters.get(owner_id)
                item = required(data, "item")
                if (
                    isinstance(item, dict)
                    and dict(item.get("mechanics") or {}).get("spellcasting") is not None
                ):
                    if current.campaign_id is None:
                        raise ValueError(
                            "magic item spell hydration requires a campaign-bound character"
                        )
                    item = hydrate_magic_item_spell_artifacts(
                        current.campaign_id,
                        item,
                    )
                result = character_inventory_add(
                    owner_id,
                    item,
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
            elif action == "update":
                result = character_inventory_update(
                    owner_id,
                    required(data, "item_id"),
                    required(data, "patch"),
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
            elif action == "remove":
                result = character_inventory_remove(
                    owner_id,
                    required(data, "item_id"),
                    data.get("quantity"),
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
            elif action == "equip":
                result = character_inventory_equip(
                    owner_id,
                    required(data, "item_id"),
                    required(data, "slot"),
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
            elif action == "recharge":
                result = character_inventory_recharge(
                    owner_id,
                    required(data, "item_id"),
                    required(data, "trigger"),
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
            else:
                result = character_ammunition_consume(
                    owner_id,
                    required(data, "weapon_id"),
                    data.get("quantity", 1),
                    principal_id,
                    expected_revision,
                    idempotency_key,
                )
        elif action == "add":
            result = party_inventory_add(
                owner_id, required(data, "item"), principal_id, expected_revision, idempotency_key
            )
        else:
            result = party_inventory_remove(
                owner_id,
                required(data, "item_id"),
                data.get("quantity"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        return facade_result(action, result)

    @mcp.tool()
    def inventory_transfer(
        mode: Literal["character_to_character", "party_to_character", "character_to_party"],
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Transfer inventory with the revision contract required by every affected owner."""
        data = facade_payload(payload)
        if mode == "character_to_character":
            result = character_inventory_transfer(
                required(data, "source_character_id"),
                required(data, "target_character_id"),
                required(data, "item_id"),
                data.get("quantity"),
                principal_id,
                required(data, "expected_campaign_revision"),
                required(data, "expected_source_revision"),
                required(data, "expected_target_revision"),
                idempotency_key,
            )
        else:
            direction = "withdraw" if mode == "party_to_character" else "deposit"
            result = party_inventory_transfer(
                required(data, "campaign_id"),
                required(data, "character_id"),
                required(data, "item_id"),
                direction,
                data.get("quantity"),
                principal_id,
                required(data, "expected_campaign_revision"),
                required(data, "expected_character_revision"),
                idempotency_key,
            )
        return facade_result(mode, result)

    @mcp.tool()
    def wallet_change(
        owner: Literal["character", "party"],
        action: Literal["adjust", "transfer_to_character", "transfer_from_character"],
        owner_id: str,
        denomination: str,
        amount: int,
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Adjust a wallet or transfer money through the party with all affected revisions."""
        data = facade_payload(payload)
        if action == "adjust":
            result = (
                character_wallet_adjust(
                    owner_id, denomination, amount, principal_id, expected_revision, idempotency_key
                )
                if owner == "character"
                else party_wallet_adjust(
                    owner_id, denomination, amount, principal_id, expected_revision, idempotency_key
                )
            )
        else:
            if owner != "party":
                raise ValueError("wallet transfers use the party as owner")
            direction = "withdraw" if action == "transfer_to_character" else "deposit"
            result = party_wallet_transfer(
                owner_id,
                required(data, "character_id"),
                denomination,
                amount,
                direction,
                principal_id,
                required(data, "expected_campaign_revision"),
                required(data, "expected_character_revision"),
                idempotency_key,
            )
        return facade_result(action, result)

    @mcp.tool()
    def character_state_change(
        character_id: str,
        action: Literal[
            "effect_add",
            "effect_remove",
            "resource_set",
            "exhaustion_set",
            "damage",
            "heal",
            "revive",
            "level_advance",
            "resource_sync",
            "source_state",
            "stand",
            "knock_prone",
        ],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Apply one noncombat character state transition with its D&D-specific validation."""
        data = facade_payload(payload)
        if action == "effect_add":
            result = character_effect_add(
                character_id,
                required(data, "effect"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "effect_remove":
            result = character_effect_remove(
                character_id,
                required(data, "effect_id"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "resource_set":
            result = character_resource_set(
                character_id,
                required(data, "resource"),
                required(data, "value"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "exhaustion_set":
            result = character_exhaustion_set(
                character_id,
                required(data, "value"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "damage":
            result = character_apply_damage(
                character_id,
                required(data, "parts"),
                critical=data.get("critical", False),
                knock_out=data.get("knock_out", False),
                melee=data.get("melee", False),
                principal_id=principal_id,
                expected_revision=expected_revision,
                idempotency_key=idempotency_key,
            )
        elif action == "heal":
            result = character_apply_healing(
                character_id,
                required(data, "amount"),
                source_actor_id=data.get("source_actor_id"),
                spell_id=data.get("spell_id"),
                spell_level=data.get("spell_level"),
                principal_id=principal_id,
                expected_revision=expected_revision,
                idempotency_key=idempotency_key,
            )
        elif action == "revive":
            unexpected = set(data) - {
                "elapsed_days",
                "soul_willing",
                "body_intact",
                "source_ref",
                "reason",
                "source_actor_id",
            }
            if unexpected:
                raise ValueError(
                    "revive payload accepts only elapsed_days, soul_willing, body_intact, "
                    "source_ref, reason, and source_actor_id; "
                    f"unexpected fields: {sorted(unexpected)}"
                )
            result = character_apply_raise_dead(
                character_id,
                elapsed_days=required(data, "elapsed_days"),
                soul_willing=required(data, "soul_willing"),
                body_intact=required(data, "body_intact"),
                source_ref=required(data, "source_ref"),
                reason=required(data, "reason"),
                source_actor_id=data.get("source_actor_id"),
                principal_id=principal_id,
                expected_revision=expected_revision,
                idempotency_key=idempotency_key,
            )
        elif action == "level_advance":
            unexpected = set(data) - {"class_name", "hp_method", "reason", "source_ref"}
            if unexpected:
                raise ValueError(
                    "level_advance payload accepts only class_name, hp_method, reason, "
                    f"and source_ref; unexpected fields: {sorted(unexpected)}"
                )
            result = character_level_advance(
                character_id,
                required(data, "class_name"),
                required(data, "hp_method"),
                required(data, "reason"),
                required(data, "source_ref"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "resource_sync":
            unexpected = set(data) - {"reason"}
            if unexpected:
                raise ValueError(
                    "resource_sync payload accepts only reason; "
                    f"unexpected fields: {sorted(unexpected)}"
                )
            result = character_class_resources_synchronize(
                character_id,
                required(data, "reason"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "source_state":
            result = character_source_state_initialize(
                character_id,
                required(data, "state"),
                required(data, "source_ref"),
                required(data, "reason"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "stand":
            result = character_stand(
                character_id,
                principal_id,
                expected_revision,
                idempotency_key,
            )
        elif action == "knock_prone":
            result = character_knock_prone(
                character_id,
                principal_id,
                expected_revision,
                idempotency_key,
            )
        else:
            raise ValueError(f"unsupported character state action: {action}")
        return facade_result(action, result)

